L2_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE"
L2_1.m_Talk_KOREA = "간호사 언니가 내일이면 눈에 감은 붕대를 풀 수 있대."
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "看護師のお姉さんが明日には目に巻いた包帯を外せるって言ってた。"
L2_1.m_Talk_ENG = "The nurse said they'll take off the bandages from my eyes tomorrow."
L2_1.m_Talk_TWN = "護士姐姐說，明天就能解開眼睛上的繃帶了。"
L2_1.m_Talk_THA = "พยาบาลบอกว่าพรุ่งนี้จะเอาผ้าปิดตาออก"
L2_1.m_Talk_VTN = "Chị y tá nói ngày mai họ sẽ tháo băng ra khỏi mắt tôi."
L2_1.m_Talk_SCN = "护士姐姐说，明天就能解开眼睛上的绷带了。"
L2_1.m_Talk_DEU = "Die Krankenschwester meinte, morgen kann ich die Bandagen von den Augen nehmen."
L2_1.m_Talk_FRA = "L'infirmière a dit qu'ils enlèveront les bandages de mes yeux demain."
L3_1 = {}
L3_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 31353
L3_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Talk_KOREA = "이 일기장은 간호사 언니가 미리 글씨 연습을 하자고 준 거야."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "この日記帳は、看護師のお姉さんが文字を書く練習用にくれたの。"
L3_1.m_Talk_ENG = "She gave me this diary so I can practice writing afterwards."
L3_1.m_Talk_TWN = "這本日記是護士姐姐為了讓我預先練習寫字給我的。"
L3_1.m_Talk_THA = "เธอให้สมุดบันทึกมา ฉันจะได้หัดเขียน"
L3_1.m_Talk_VTN = "Chị ấy đã cho tôi cuốn nhật ký này để tôi có thể tập viết sau đó."
L3_1.m_Talk_SCN = "这日记本是护士姐姐为了让我练习写字给我的。"
L3_1.m_Talk_DEU = "Und mit diesem Tagebuch soll ich danach wieder Schreiben üben."
L3_1.m_Talk_FRA = "Elle m'a donné ce journal pour que je puisse m'entraîner à écrire ensuite."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 31353
L4_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Talk_KOREA = "하루에 있었던 일 중에 적고 싶은 일을 적으면 된대."
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "一日の出来事の中で書きたいことを書けばいいんだって。"
L4_1.m_Talk_ENG = "She said I can write down whatever happened during the day."
L4_1.m_Talk_TWN = "她說我可以把一天發生的事情中，想寫的事情寫在這本日記上。"
L4_1.m_Talk_THA = "เธอบอกว่าให้ฉันเขียนอะไรก็ได้ที่เกิดขึ้นระหว่างวัน"
L4_1.m_Talk_VTN = "Chị ấy nói tôi có thể viết ra bất cứ chuyện gì đã xảy ra trong ngày."
L4_1.m_Talk_SCN = "她说我可以在这个日记本上写我想写的事。"
L4_1.m_Talk_DEU = "Sie meinte, ich soll einfach alles, was den Tag über passiert, aufschreiben."
L4_1.m_Talk_FRA = "Elle a dit que je pouvais écrire tout ce qui se passait dans la journée."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 31353
L5_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Talk_KOREA = "하지만 병원에서는 매일매일이 똑같아. 적고 싶은 일이 없어."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "だけど、病院の中じゃ毎日同じことばかり。書きたいことがない。"
L5_1.m_Talk_ENG = "But every day is the same at the hospital. There's nothing I want to write about here."
L5_1.m_Talk_TWN = "但在醫院裡，每天的生活都一樣，沒有什麼想寫的事情。"
L5_1.m_Talk_THA = "แต่ทุกวันที่โรงพยาบาลก็เหมือนกันไปหมด ไม่มีอะไรที่ฉันอยากเขียนถึงเลย"
L5_1.m_Talk_VTN = "Nhưng ngày nào ở bệnh viện cũng giống nhau cả. Tôi không có gì muốn viết trong lúc ở đây."
L5_1.m_Talk_SCN = "但在医院里，每天的生活都是一样的。没有什么想写的事情。"
L5_1.m_Talk_DEU = "Aber im Krankenhaus ist jeder Tag gleich. Es gibt nichts, worüber ich gerne schreiben würde."
L5_1.m_Talk_FRA = "Mais tous les jours se ressemblent à l'hôpital. Il n'y a rien que j'aie envie d'écrire ici."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 31353
L6_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Talk_KOREA = "그러니까 내가 쓰고 싶은 얘기를 쓸래."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "だから私が書きたい話を書くね。"
L6_1.m_Talk_ENG = "So I'm just going to write whatever I want."
L6_1.m_Talk_TWN = "所以我要把我想到的都寫上去。"
L6_1.m_Talk_THA = "ดังนั้น ฉันจะเขียนอะไรตามใจชอบแล้วกัน"
L6_1.m_Talk_VTN = "Vậy nên tôi sẽ chỉ viết bất cứ điều gì tôi muốn."
L6_1.m_Talk_SCN = "所以我要把我想到的都写上去。"
L6_1.m_Talk_DEU = "Also schreibe ich einfach, worauf ich Lust habe."
L6_1.m_Talk_FRA = "Je vais donc écrire ce que je veux."
L7_1 = {}
L7_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 31353
L7_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Talk_KOREA = "간호사 언니가 일기장은 보여 주고 싶은 사람에게만 보여 줘도 된다고 했으니까."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "看護師のお姉さんが、日記帳は見せたい人にだけ見せてもいいって言ってたから。"
L7_1.m_Talk_ENG = "The nurse said I don't have to show my diary to anyone except those I want."
L7_1.m_Talk_TWN = "護士姐姐說可以只把日記拿給我想分享的人看。"
L7_1.m_Talk_THA = "พยาบาลบอกว่าฉันไม่จำเป็นต้องเอาสมุดบันทึกให้ใครดู ยกเว้นคนที่ฉันอยากให้ดู"
L7_1.m_Talk_VTN = "Chị y tá nói rằng tôi không cần phải đưa nhật ký của mình cho bất kỳ ai, ngoại trừ những người tôi muốn."
L7_1.m_Talk_SCN = "护士姐姐说可以只给我想分享的人看日记本。"
L7_1.m_Talk_DEU = "Die Krankenschwester meinte, ich muss mein Tagebuch niemandem zeigen, wenn ich nicht will."
L7_1.m_Talk_FRA = "L'infirmière a dit que j'ai pas à montrer mon journal à qui que ce soit, sauf à ceux que je veux."
