L13_1 = {}
L13_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 31353
L13_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Talk_KOREA = "내가 있던 창고에는 사람이 많았습니다."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "私がいた倉庫には大勢の人がいました。"
L13_1.m_Talk_ENG = "There were a lot of people in the warehouse I was in."
L13_1.m_Talk_TWN = "我所在的倉庫裡有很多人。"
L13_1.m_Talk_THA = "โกดังที่ฉันอยู่มีคนอยู่กันเยอะ"
L13_1.m_Talk_VTN = "Có rất nhiều người trong nhà kho mà tôi đã ở."
L13_1.m_Talk_SCN = "我所在的仓库里有很多人。"
L13_1.m_Talk_DEU = "Da waren ’ne Menge Leute in dem Lager, in dem ich war."
L13_1.m_Talk_FRA = "Il y avait beaucoup de gens dans l'entrepôt dans lequel j'étais."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 31353
L14_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Talk_KOREA = "가끔씩 여러 명이 나가고, 여러 명이 들어왔어요."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "時々何人かの人が出ていって、また何人かが入ってきました。"
L14_1.m_Talk_ENG = "Sometimes several people would go out, and new people would come."
L14_1.m_Talk_TWN = "偶爾會有很多人出去，很多人進來。"
L14_1.m_Talk_THA = "บางครั้งก็มีคนออกไป แล้วก็มีคนหน้าใหม่เข้ามา"
L14_1.m_Talk_VTN = "Đôi khi một số người sẽ đi ra và một số người mới sẽ đi vào."
L14_1.m_Talk_SCN = "偶尔会有很多人出去，很多人进来。"
L14_1.m_Talk_DEU = "Manchmal sind ein paar weggegangen, und dann sind wieder Neue gekommen."
L14_1.m_Talk_FRA = "Parfois, plusieurs personnes partaient, et d'autres prenaient leur place."
L15_1 = {}
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 31353
L15_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
