L16_1 = {}
L16_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 31353
L16_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Talk_KOREA = "처음 오는 사람들은 울기도 하고, 비명을 지르기도 하고......"
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "初めて来た人は泣いたり、悲鳴を上げたりするけれど……"
L16_1.m_Talk_ENG = "At first, they would cry or scream..."
L16_1.m_Talk_TWN = "第一次來的人有哭的，也有尖叫的……"
L16_1.m_Talk_THA = "ตอนแรกพวกเขาจะร้องไห้หรือกรีดร้อง..."
L16_1.m_Talk_VTN = "Lúc đầu, bọn họ sẽ gào khóc hoặc la hét..."
L16_1.m_Talk_SCN = "第一次来的人有哭的，也有尖叫的……"
L16_1.m_Talk_DEU = "Zuerst haben sie geweint und geschrien …"
L16_1.m_Talk_FRA = "Au début, ils pleuraient ou criaient."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 31353
L17_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Talk_KOREA = "그러다가 몇 번 어른들에게 불려가면 아무 말도 없이 구석에 앉아 있게 됩니다."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "そのうち何回か大人たちに呼ばれると、何も言わずに隅っこでうずくまるようになります。"
L17_1.m_Talk_ENG = "But when the grown-ups take them away a few times, they learn to sit quietly in the corner."
L17_1.m_Talk_TWN = "他們被大人們叫出去幾次，回來後就會縮在角落，一句話也不說。"
L17_1.m_Talk_THA = "แต่พอผู้ใหญ่พาตัวไปสองสามครั้ง ทุกคนก็เรียนรู้ที่จะนั่งเงียบๆ ที่มุมห้อง"
L17_1.m_Talk_VTN = "Nhưng khi đám người lớn dẫn họ ra ngoài một vài lần, họ đã học được cách ngồi im trong góc."
L17_1.m_Talk_SCN = "他们被大人们叫出去几次，回来后就会缩在角落一句话也不说。"
L17_1.m_Talk_DEU = "Aber die Großen haben sie ein paar mal mitgenommen und dann haben sie gelernt, dass sie ruhig in der Ecke sitzen müssen."
L17_1.m_Talk_FRA = "Mais après avoir été emmenés plusieurs fois par les adultes, ils apprenaient à rester silencieux dans un coin."
L18_1 = {}
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 31353
L18_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L18_1.m_bWaitClick = false
