L19_1 = {}
L19_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 31353
L19_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Talk_KOREA = "나는 그러기 싫어서, 얌전히 지냈어요."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "私はそうなるのが嫌で、大人しく過ごしました。"
L19_1.m_Talk_ENG = "I stayed quiet because I didn't want that to happen to me."
L19_1.m_Talk_TWN = "我不想變成那樣，所以一直都乖乖的。"
L19_1.m_Talk_THA = "ฉันอยู่เงียบๆ เพราะฉันไม่อยากให้มันเกิดขึ้นกับฉัน"
L19_1.m_Talk_VTN = "Tôi im lặng vì tôi không muốn điều đó xảy ra với mình."
L19_1.m_Talk_SCN = "我不想变成那样，所以一直都很老实。"
L19_1.m_Talk_DEU = "Ich war immer ganz leise, damit mir das nicht passiert."
L19_1.m_Talk_FRA = "Je restais sage, parce que je ne voulais pas que ça m'arrive."
L20_1 = {}
L20_1.m_CutScenProcessKey = 20
