L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 31353
L21_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Talk_KOREA = "그날까지는요."
