L21_1.m_Talk_JPN = "あの日までは。"
L21_1.m_Talk_ENG = "Until that day, that is."
L21_1.m_Talk_TWN = "直到那天。"
L21_1.m_Talk_THA = "จนกระทั่งวันนั้นมาถึง"
L21_1.m_Talk_VTN = "Cho đến ngày đó."
L21_1.m_Talk_SCN = "直到那天。"
L21_1.m_Talk_DEU = "Zumindest bis zu diesem einen Tag."
L21_1.m_Talk_FRA = "Jusqu'à ce jour, bien sûr."
