L24_1.m_Talk_KOREA = "잡았다! 이 꼬맹이!"
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "捕まえたぞ！　この小娘！"
L24_1.m_Talk_ENG = "I got you! You little punk!"
L24_1.m_Talk_TWN = "抓到了！這小鬼！"
L24_1.m_Talk_THA = "จับได้แล้ว! ยัยเด็กเหลือขอ!"
L24_1.m_Talk_VTN = "Tao bắt được mày rồi! Đứa nhỏ hỗn xược này!"
L24_1.m_Talk_SCN = "抓到了！这小鬼！"
L24_1.m_Talk_DEU = "Hab ich dich, du kleiner Strolch!"
L24_1.m_Talk_FRA = "Je te tiens ! Petite morveuse !"
