L29_1 = {}
L29_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 31353
L29_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "REVELB_NPC_NULL_NULL"
L29_1.m_Pos = "R_M_I"
L29_1.m_Talk_KOREA = "휴우. 앞도 제대로 못 보는 꼬마가 무슨 생각으로 도망친 거야? 귀찮게시리."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "ふう。ちゃんと前も見えない小娘が何のつもりで逃げたんだ？　面倒くせぇな。"
L29_1.m_Talk_ENG = "Phew... What's a blind kid doing running away? It's such a hassle."
L29_1.m_Talk_TWN = "呼。路都看不清的小鬼還想逃跑？真麻煩。"
L29_1.m_Talk_THA = "เฮ้อ... เด็กตาบอดอะไรที่คิดจะหนี? วุ่นวายชะมัด"
L29_1.m_Talk_VTN = "Phù... Một đứa trẻ mù thì chạy trốn làm cái quái gì vậy? Đúng là rắc rối."
L29_1.m_Talk_SCN = "呼。路都看不清的小鬼还想着逃跑？真麻烦。"
L29_1.m_Talk_DEU = "Häh? Warum rennt denn ein blindes Balg weg? So ein Ärger."
L29_1.m_Talk_FRA = "Pfiou... Qu'est-ce qu'une petite aveugle fait à s'enfuir comme ça ? C'est tellement galère."
L30_1 = {}
L30_1.m_CutScenKey_Talk = "COUNTERCASE_GAEUN_NORMAL_3@30#Talk"
L30_1.m_CutScenProcessKey = 30
