L30_1.m_Pos = "C"
L30_1.m_Crash = 30
L30_1.m_Talk_KOREA = "놔......! 이거 놔아......!"
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "離して……！　離してよ……！"
L30_1.m_Talk_ENG = "Let go! Let go of me!"
L30_1.m_Talk_TWN = "放……！放開我……！"
L30_1.m_Talk_THA = "ปล่อยนะ! ปล่อยฉันนะ!"
L30_1.m_Talk_VTN = "Bỏ tôi ra! Buông tôi ra!"
L30_1.m_Talk_SCN = "放开……！放开我……！"
L30_1.m_Talk_DEU = "Lass los! Lass mich los!"
L30_1.m_Talk_FRA = "Lâchez-moi !"
