L34_1 = "COUNTERCASE_GAEUN_NORMAL_3@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 31353
L33_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "REVELA_NPC_NULL_NULL"
L34_1 = "L"
L33_1.m_Pos = L34_1
L34_1 = "허 참, 쓰레기나 주워 먹고 살 걸 입혀 주고 재워 줬더니 은혜를 모르네."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ったく、ゴミをあさって生きてるところを面倒見てやったのに、恩知らずだな。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "You ungrateful little thing. We fed you and gave you a place to sleep when you could've spent your entire life on the street."
L33_1.m_Talk_ENG = L34_1
L34_1 = "真是的，給妳這乞丐有吃有穿有住，竟然這麼不知感恩。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ยัยเด็กไม่รู้จักบุญคุณคน เราให้อาหารและให้ที่นอน ทั้งที่แกอาจต้องอยู่ข้างถนนตลอดชีวิต"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tên nhóc con vô ơn. Bọn tao đã cho mày đồ ăn và chỗ ngủ trong khi mày có thể sẽ phải dành cả đời vất vưởng trên đường phố."
L33_1.m_Talk_VTN = L34_1
L34_1 = "真是的，给你这乞丐吃的穿的，到头来还不懂得报恩。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Du undankbares kleines Ding. Wir haben dir zu Essen und ein Dach über dem Kopf gegeben, damit du nicht dein ganzes Leben auf der Straße verbringen musst."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Espèce de petite chose ingrate. Nous t'avons nourrie, nous t'avons donné un toit alors que tu aurais pu passer toute ta vie dans la rue."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "COUNTERCASE_GAEUN_NORMAL_3@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 31353
L34_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "REVELA_NPC_NULL_NULL"
L35_1 = "L"
L34_1.m_Pos = L35_1
L35_1 = "참 신기해. 이 장사 하다 보면 꼭 이렇게 현실파악 못하는 애가 하나씩 섞여 있다니까."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "不思議だよな。この商売をやっていると、こうやって現実がわからないやつが一人は必ずいるもんだから。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "It's fascinating, really. Sometimes in this line of business, you always find a kid who just doesn't get how it works."
L34_1.m_Talk_ENG = L35_1
L35_1 = "真是不可思議啊。這生意做這麼久了，總會有那麼幾個認不清現實的孩子。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "น่าสนใจจริงๆ นะ บางครั้งในธุรกิจแบบนี้ก็มีเด็กที่ไม่เข้าใจว่ามันเป็นยังไง"
L34_1.m_Talk_THA = L35_1
L35_1 = "Nghe hấp dẫn nhỉ. Đôi khi trong cái ngành này, mày luôn thấy một đứa trẻ không hiểu cuộc sống vận hành như thế nào."
L34_1.m_Talk_VTN = L35_1
L35_1 = "真是神奇啊。这生意做久了，总有那么几个看不清现实的孩子。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Das ist echt faszinierend. In unserem Job triffst du immer wieder auf irgendein Kind, das es einfach nicht verstehen will."
L34_1.m_Talk_DEU = L35_1
L35_1 = "C'est fascinant, vraiment. Parfois, dans ce business, on trouve un gosse qui est incapable de comprendre comment ça marche."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "COUNTERCASE_GAEUN_NORMAL_3@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 31353
L35_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "REVELB_NPC_NULL_NULL"
L36_1 = "R"
L35_1.m_Pos = L36_1
L36_1 = "어허, 장사가 아니라 반정부 활동이지. 누가 들으면 어쩌려고."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "こら、商売じゃなくて反政府活動だろ。誰かに聞かれたらどうするんだ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Come on now, this isn't business. It's an insurgency. We wouldn't want anyone to get the wrong idea."
L35_1.m_Talk_ENG = L36_1
L36_1 = "哦吼，這可不叫生意，叫反政府行動。要是被別人聽到怎麼辦？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ไม่เอาน่า นี่ไม่ใช่ธุรกิจ นี่คือจลาจล เราไม่อยากให้ใครเข้าใจผิด"
L35_1.m_Talk_THA = L36_1
L36_1 = "Thôi nào, đây không phải là ngành nghề gì hết. Đây là một cuộc nổi dậy. Chúng ta sẽ không muốn có người hiểu nhầm ý tưởng của chúng ta đâu."
L35_1.m_Talk_VTN = L36_1
L36_1 = "哦吼，这可不叫生意，应该是反政府行动吧。要是别人听到怎么办。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Das ist kein „Job“. Das ist ein Aufstand. Wir wollen doch keine Missverständnisse verursachen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Allons, ce n'est pas du business. C'est une insurrection. Il ne faudrait pas que quelqu'un se fasse de fausses idées."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
