L40_1 = 40
L39_1.m_Crash = L40_1
L40_1 = "아악! 젠장, 이 빌어먹을 꼬마가 내 손을 물어!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "うあっ！　くそ、この小娘手を嚙みやがった！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Ow! This blasted kid is biting my hand!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "啊啊！該死，這個死小鬼咬我的手！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "โอ๊ย! เด็กเวรนี่กัดมือฉัน!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Ối! Đứa trẻ láo toét này cắn tay tao!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "啊啊！该死，这小鬼咬我的手！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Au! Das verfluchte Balg hat mich gebissen!"
L39_1.m_Talk_DEU = L40_1
