L44_1 = "R"
L43_1.m_Pos = L44_1
L44_1 = "조심해. 다음에 정부군 놈들과 싸울 때 인간 방패로 써야 한다고."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "気をつけろよ。今度政府軍と戦う時に、人間の盾として使わなきゃならないんだ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Easy now. We have to use her as a human shield when we fight the government forces next time."
L43_1.m_Talk_ENG = L44_1
L44_1 = "小心點。下次和政府軍開打的時候，還得用這小妞當人肉盾牌呢。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ใจเย็นๆ เราต้องใช้เธอเป็นโล่มนุษย์เวลาสู้กับกองกำลังของรัฐบาลคราวหน้านะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Bình tĩnh đi nào. Chúng ta phải lợi dụng nó làm lá chắn sống khi chiến đấu với lực lượng chính phủ vào lần tới đấy."
L43_1.m_Talk_VTN = L44_1
L44_1 = "小心点。下次和政府那帮家伙打的时候，还得用这小鬼做人肉盾牌呢。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Das reicht. Sie ist unser menschlicher Schutzschild, wenn wir das nächste Mal gegen die Regierungstruppen kämpfen."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Du calme. Nous devons nous en servir comme bouclier humain la prochaine fois face aux forces gouvernementales."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "COUNTERCASE_GAEUN_NORMAL_3@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 31353
L44_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L44_1.m_bWaitClick = true
