L44_1.m_CharStrID = "REVELB_NPC_NULL_NULL"
L45_1 = "R"
L44_1.m_Pos = L45_1
L45_1 = "다리라도 부러져서 걷는 데 지장 생기면 보스가 뭐라고 하겠어?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "脚でも折って、歩けなくなったらボスに何言われるかわからないぞ？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "The boss will give you a mouthful if you break her legs or something."
L44_1.m_Talk_ENG = L45_1
L45_1 = "如果她腳斷了沒辦法走，你要怎麼跟老闆交代？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "บอสได้ด่านายแน่ ถ้านายทำเธอขาหักหรือบาดเจ็บ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Ông trùm sẽ cho mày nằm liệt giường nếu mày dám làm gãy chân con bé."
L44_1.m_Talk_VTN = L45_1
L45_1 = "如果她脚断了没法走，你要怎么跟老板交代？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Der Boss zieht dir die Ohren lang, wenn du ihre Beine brichst oder so."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Le boss va t'engueuler si tu lui casses les jambes."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
