L46_1 = "L"
L45_1.m_Pos = L46_1
L45_1.m_Crash = 30
L46_1 = "헛소리 말고 잘 붙들고 있기나 해!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "じゃあちゃんと捕まえとけよ！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Shut up and just hold on to her!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "別扯這些有的沒的，給我好好抓住她！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "หุบปากแล้วจับเธอไว้น่า!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Câm mồm và lo bắt con bé lại đi!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "别扯这些有的没的，给我好好抓住她！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Halt die Schnauze und halt sie fest!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Taisez-vous et tenez-la bien !"
L45_1.m_Talk_FRA = L46_1
