L46_1.m_CharStrID = "REVELA_NPC_NULL_NULL"
L47_1 = "L"
L46_1.m_Pos = L47_1
L47_1 = "이런 것들은 매를 맞아야 정신을 차리지......!"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "こういうやつは痛い目にあわないと言うことを聞かないんだ……！"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I'm going to beat some sense into the little twerp!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "這些東西就是得揍一頓才會清醒啊……！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ฉันจะตีให้นังนี่สำนึกเลย!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tao sẽ cho con nhóc khốn nạn đó một bài học!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "这些玩意儿就是得揍了才清醒啊……！"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich prügel’ diesem Welpen etwas Vernunft ein!"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Je vais lui apprendre les bonnes manières à cette morveuse !"
L46_1.m_Talk_FRA = L47_1
