L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 31353
L48_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "REVELB_NPC_NULL_NULL"
L49_1 = "R"
L48_1.m_Pos = L49_1
L48_1.m_Crash = 20
L49_1 = "......바, 방금 들었냐? 여기 침식지대였어?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "……おい、今の聞いたか？　ここって侵食地帯だったのか？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "D-did you just hear that? Was this supposed to be a Corrupted Area?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "……你、你聽到了嗎，剛才的聲音？這裡是侵蝕地區嗎？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ดะ-ได้ยินนั่นมั้ย? เสียงจากบริเวณที่ถูกคอร์รัปต์รึเปล่า?"
L48_1.m_Talk_THA = L49_1
L49_1 = "M-mày vừa nghe thấy gì không? Đây là Khu Vực Bị Ăn Mòn hả?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "……听，听到了吗，刚才的声音？这里是侵蚀地区吗？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "H-hast du das gehört? Soll das hier nicht ein Verderbtes Gebiet sein?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "V-Vous avez entendu ? C'est pas censé être une zone corrompue, si ?"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "COUNTERCASE_GAEUN_NORMAL_3@49#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 31353
L49_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
