L50_1 = "L"
L49_1.m_Pos = L50_1
L50_1 = 40
L49_1.m_Crash = L50_1
L50_1 = "제, 제기랄! 도망쳐야 해! 침식체라도 나오면 끝이라고!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "く、くそ！　逃げるんだ！　侵食体に出くわしたら終わりだぞ！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "D-dang it! We have to get out of here! We're dead meat if any C.O.s pop out!"
L49_1.m_Talk_ENG = L50_1
L50_1 = "該、該死！得快點逃！侵蝕體過來就完蛋了！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "บ้าเอ๊ย! เราต้องรีบไปจากที่นี่! ถ้ามีวัตถุคอร์รัปต์โผล่มา พวกเราได้ตายแหง!"
L49_1.m_Talk_THA = L50_1
L50_1 = "Chết tiệt! Chúng ta phải ra khỏi đây! Chúng ta sẽ chết nếu đám Đối Tượng B.A.M nhảy ra đấy!"
L49_1.m_Talk_VTN = L50_1
L50_1 = "可，可恶！得快点逃！要是碰上侵蚀体就完蛋了！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "V-verflixt! Wir müssen weg hier. Wenn irgendwelche C. O.s auftauchen, sind wir so gut wie tot!"
L49_1.m_Talk_DEU = L50_1
L50_1 = "M-Merde ! Faut qu'on se bouge ! Si des O.C. se pointent, on est foutus !"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
