L1_1.m_Crash = 30
L2_1 = "내버려 둬! 인간 방패로 쓸 고아들은 이 나라에 넘쳐나니까!"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "放っておけ！　盾に使う孤児なんて、この国にいくらでもいる！"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Leave her here! There's plenty of other orphans in this country to use as human shields!"
L1_1.m_Talk_ENG = L2_1
L2_1 = "別管了！用來當人肉盾牌的孤兒而已，這國家要多少有多少！"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ปล่อยไว้ที่นี่แหละ! ประเทศนี้มีเด็กกำพร้าให้ใช้เป็นโล่มนุษย์อีกเยอะแยะ!"
L1_1.m_Talk_THA = L2_1
L2_1 = "Kệ nó! Đất nước này còn rất nhiều trẻ mồ côi khác để chúng ta dùng làm khiên chắn sống!"
L1_1.m_Talk_VTN = L2_1
L2_1 = "别管了！用来当人肉盾牌的孤儿而已，这国家要多少有多少！"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Die lassen wir hier! Dieses Land hat mehr als genug Waisen, die wir als menschliche Schutzschilde benutzen können!"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Laisse-la ici ! Y'a plein d'autres orphelins qui peuvent servir de bouclier humain dans ce pays !"
L1_1.m_Talk_FRA = L2_1
