L10_1.m_Talk_THA = L11_1
L11_1 = "Nếu được sinh ra lần nữa... mình muốn có một cuộc sống bình thường..."
L10_1.m_Talk_VTN = L11_1
L11_1 = "如果能投胎转世……我想过普通人的生活…… "
L10_1.m_Talk_SCN = L11_1
L11_1 = "Wenn ich jemals wiedergeboren werde … wünsche ich mir ein normales Leben … "
L10_1.m_Talk_DEU = L11_1
L11_1 = "Si je renais un jour... Je veux avoir une vie normale... "
L10_1.m_Talk_FRA = L11_1
