L17_1 = "USER_ADMIN_NULL_QM"
L16_1.m_CharStrID = L17_1
L17_1 = "네가 다시 태어나기 전까지는 시간이 아주 많이 남아 있거든."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "君が生まれ変わるまでは、時間がまだたくさん残っているんだよ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Because you still got many years ahead of you until your next chance at life."
L16_1.m_Talk_ENG = L17_1
L17_1 = "因為妳離投胎還早得很呢。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เพราะเธอยังต้องอยู่ไปอีกหลายปีกว่าจะได้เกิดใหม่"
L16_1.m_Talk_THA = L17_1
L17_1 = "Vì bạn vẫn còn nhiều năm đang chờ cho đến khi có cơ hội được sinh ra lại."
L16_1.m_Talk_VTN = L17_1
L17_1 = "因为你离投胎还远着呢。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Denn du hast noch viele Jahre zu leben vor dir, bevor du die Chance darauf bekommst."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Tu as encore beaucoup d'années devant toi avant le début de ta prochaine vie."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
