L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 31353
L17_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "USER_ADMIN_NULL_QM"
L17_1.m_CharStrID = L18_1
L18_1 = "하지만 지금이라도 괜찮다면 내가 조금은 도와 줄 수 있을 것 같은데."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "今からでもよければ、私が少しは力になってあげられそうだが。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "But I think I could help you out a little, if you don't mind."
L17_1.m_Talk_ENG = L18_1
L18_1 = "但如果妳不介意是現在的話，我倒是能幫妳一點小忙。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "แต่ฉันว่าฉันช่วยเธอได้นิดหน่อยนะ ถ้าเธอไม่ว่าอะไร"
L17_1.m_Talk_THA = L18_1
L18_1 = "Nhưng tôi nghĩ mình có thể giúp bạn một chút, nếu bạn không phiền."
L17_1.m_Talk_VTN = L18_1
L18_1 = "不过你不介意是现在的话，我倒是能帮你实现这个愿望。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Aber ich denke, ich könnte dir etwas helfen, wenn du es mir gestattest."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Mais je pense pouvoir t'aider un peu, si tu n'y vois pas d'inconvénient."
L17_1.m_Talk_FRA = L18_1
