L21_1 = "USER_ADMIN_NULL_QM"
L20_1.m_CharStrID = L21_1
L21_1 = "관리자...... 아니, 선생님이라고 부르렴."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "管理者……いや、先生と呼んでくれればいい。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I'm the Administrator... Never mind, just call me Teacher."
L20_1.m_Talk_ENG = L21_1
L21_1 = "管理者……不，叫我老師吧。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ฉันคือผู้บริหาร... แต่ไม่เป็นไร เรียกฉันว่าคุณครูเถอะ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tôi là Quản trị viên... Đừng bận tâm, cứ gọi tôi là Giáo Viên thôi."
L20_1.m_Talk_VTN = L21_1
L21_1 = "管理员……不，叫我老师吧。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ich bin der Administrator … Vergiss das, nenn mich einfach Lehrer."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Je suis l'Administrateur... Peu importe, appelle-moi Professeur."
L20_1.m_Talk_FRA = L21_1
