L21_1.m_CharStrID = L22_1
L22_1 = "지금은 그게 더 어울릴 것 같으니까."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "今はそのほうが似合いそうだからね。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "I think that's probably more appropriate right now."
L21_1.m_Talk_ENG = L22_1
L22_1 = "因為現在這個稱呼似乎更合適我。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ตอนนี้คำนี้น่าจะเหมาะกว่านะ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tôi nghĩ cái tên đó sẽ phù hợp hơn trong lúc này."
L21_1.m_Talk_VTN = L22_1
L22_1 = "现在，这个称呼更适合我。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Das ist momentan wohl die bessere Formulierung."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Je pense que c'est le plus adapté pour le moment."
L21_1.m_Talk_FRA = L22_1
