L22_1.m_Crash = 20
L23_1 = "가, 가까운 데에 침식체가 있어...... 어서 도망쳐......"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ち、近くに侵食体がいるの……早く逃げて……"
L22_1.m_Talk_JPN = L23_1
L23_1 = "There's a C.O. nearby... Get out of here..."
L22_1.m_Talk_ENG = L23_1
L23_1 = "附、附近有侵蝕體……快點逃……"
L22_1.m_Talk_TWN = L23_1
L23_1 = "มีวัตถุคอร์รัปต์อยู่ไม่ไกล... ไปจากที่นี่กันเถอะ..."
L22_1.m_Talk_THA = L23_1
L23_1 = "Có một Đối Tượng B.A.M ở gần đây... Đi khỏi đây..."
L22_1.m_Talk_VTN = L23_1
L23_1 = "附，附近有侵蚀体……快点跑……"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Verschwinde! In der Nähe lauert ein C. O. …"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Il y a un O.C. pas loin... Vous devez partir..."
L22_1.m_Talk_FRA = L23_1
