L25_1 = "COUNTERCASE_GAEUN_NORMAL_3@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 31353
L24_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "ADMIN_COFFIN_NULL_QM"
L24_1.m_CharStrID = L25_1
L25_1 = "내 생각을 해 주는 거니? 착한 아이구나."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "私のことを心配してくれてるのか？　優しい子だね。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Are you worried about me? Well, aren't you a nice kid."
L24_1.m_Talk_ENG = L25_1
L25_1 = "妳在擔心我嗎？真是個善良的孩子啊。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เป็นห่วงฉันเหรอ? เธอเป็นเด็กดีนะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Bạn lo lắng cho tôi hả? Chà, đúng là một đứa trẻ tử tế."
L24_1.m_Talk_VTN = L25_1
L25_1 = "在为我着想吗？真是个善良的孩子啊。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Machst du dir etwa Sorgen um mich? Du bist aber ein liebes Kind."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Tu t'inquiètes pour moi ? Quelle brave petite."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "COUNTERCASE_GAEUN_NORMAL_3@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 31353
L25_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "ADMIN_COFFIN_NULL_QM"
L25_1.m_CharStrID = L26_1
L26_1 = "하지만 걱정하지 않아도 된단다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "でも、何も心配することないよ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "But you don’t need to worry about me."
L25_1.m_Talk_ENG = L26_1
L26_1 = "但是，妳並不用擔心。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "แต่เธอไม่ต้องห่วงฉันหรอก"
L25_1.m_Talk_THA = L26_1
L26_1 = "Nhưng bạn không cần phải lo lắng cho tôi đâu."
L25_1.m_Talk_VTN = L26_1
L26_1 = "但是不用担心。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Aber du musst dir keine Sorgen um mich machen."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Mais ce n'est pas la peine."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "COUNTERCASE_GAEUN_NORMAL_3@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 31353
L26_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "ADMIN_COFFIN_NULL_QM"
L26_1.m_CharStrID = L27_1
L27_1 = "선생님에겐 재미있는 물건이 많거든."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "先生には面白い物がたくさんあるから。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I've got lots of interesting gadgets, you see."
L26_1.m_Talk_ENG = L27_1
L27_1 = "因為老師有很多有趣的東西呢。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ฉันมีอุปกรณ์น่าสนใจเยอะเลย เห็นมั้ย"
L26_1.m_Talk_THA = L27_1
L27_1 = "Tôi có rất nhiều công cụ thú vị, bạn thấy đấy."
L26_1.m_Talk_VTN = L27_1
L27_1 = "老师我有很多有趣的玩意呢。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ich habe eine Menge nützlicher Geräte, weißt du?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "J'ai toutes sortes de gadgets intéressants, tu sais."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "COUNTERCASE_GAEUN_NORMAL_3@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 31353
L27_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "ADMIN_COFFIN_NULL_QM"
L27_1.m_CharStrID = L28_1
L28_1 = "그중에는 침식체들이 우릴 볼 수 없게 만드는 물건도 있지."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "その中には、侵食体が私たちを見れないようにする物もある。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Including something that can make us invisible to the C.O.s."
L27_1.m_Talk_ENG = L28_1
L28_1 = "其中也有能讓侵蝕體看不到我們的東西。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "รวมถึงอุปกรณ์ที่ทำให้วัตถุคอร์รัปต์มองไม่เห็นเราด้วยนะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Gồm một số thứ có thể khiến chúng ta vô hình với các V.T.B.A.M"
L27_1.m_Talk_VTN = L28_1
L28_1 = "其中也有能让侵蚀体看不到我们的东西。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Unter anderem etwas, mit dem wir uns für die C. O.s unsichtbar machen können …"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Et l'un d'eux me permet notamment de nous rendre invisibles aux yeux des O.C."
L27_1.m_Talk_FRA = L28_1
