L30_1.m_fWaitTime = 0
L31_1 = "ADMIN_COFFIN_NULL_QM"
L30_1.m_CharStrID = L31_1
L31_1 = "그래. 잠시만 조용히 하고 있으면 저 녀석들은 그냥 지나가 버릴 거란다."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ああ。しばらくじっとしていたら、あいつらは素通りしていくはずだよ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "That's right. If you stay quiet for a little bit, they'll just pass us by."
L30_1.m_Talk_ENG = L31_1
L31_1 = "沒錯。只要妳能安靜一下下，它們馬上就會走掉。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ใช่แล้ว ถ้าเธออยู่เงียบๆ สักพัก เดี๋ยวมันก็ผ่านไป"
L30_1.m_Talk_THA = L31_1
L31_1 = "Đúng vậy. Nếu bạn im lặng một lát, chúng sẽ đi ngang qua chúng ta."
L30_1.m_Talk_VTN = L31_1
L31_1 = "没错。只要你能安静一会儿，它们马上就会走掉。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ja. Wenn du nur einen Moment ganz still bleibst, dann gehen sie einfach vorbei."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Tout à fait. Si tu ne fais pas de bruit, ils passeront sans nous voir."
L30_1.m_Talk_FRA = L31_1
