L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 31353
L33_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "ADMIN_COFFIN_NULL_QM"
L33_1.m_CharStrID = L34_1
L34_1 = "불안하면 손을 잡아 줄게."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "不安なら手を握ってあげよう。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "If you're nervous, I'll hold your hand."
L33_1.m_Talk_ENG = L34_1
L34_1 = "害怕的話就抓住我的手。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ถ้าเธอประหม่า ฉันจะจับมือเธอไว้นะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nếu bạn lo lắng, tôi sẽ nắm tay bạn."
L33_1.m_Talk_VTN = L34_1
L34_1 = "如果害怕就抓住我的手。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Gib mir deine Hand, wenn du aufgeregt bist."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je peux te tenir la main, si tu as peur."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "COUNTERCASE_GAEUN_NORMAL_3@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 31353
L34_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L35_1 = "ADMIN_COFFIN_NULL_QM"
L34_1.m_CharStrID = L35_1
L35_1 = "자, 무서워하지 않아도 돼. 선생님도 네 옆에 계속 있을 거란다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ほら、怖がることはない。先生は君のそばにずっといるからね。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "There, there. You don't have to be afraid anymore. I'll stay by your side."
L34_1.m_Talk_ENG = L35_1
L35_1 = "來，不用擔心。老師會一直在妳身邊的。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "โอ๋ๆ ไม่ต้องกลัวแล้วนะ ฉันจะอยู่ข้างเธอเอง"
L34_1.m_Talk_THA = L35_1
L35_1 = "Được rồi, được rồi. Bạn không cần phải sợ hãi nữa. Tôi sẽ ở bên cạnh bạn."
L34_1.m_Talk_VTN = L35_1
L35_1 = "不用害怕。老师会一直在你身边的。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Alles wird gut. Du brauchst keine Angst mehr haben. Ich bleibe bei dir."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Voilà. Tu n'as plus rien à craindre. Je suis avec toi."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
