L36_1 = "그, 그럼...... 나...... 정말 살 수 있는 거야?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "じゃ、じゃあ……私……本当に生きられるの？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Y-you mean... I... don't have to die now?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "那、那麼……我……我真的能活下去了嗎？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ปะ-แปลว่า... หนู... ไม่ต้องตายแล้วเหรอ?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ý-ý anh là... tôi... sẽ không chết sao?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "那，那么……我……我真的能活下去吗？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "D-du meinst … ich muss nicht … sterben?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Vous voulez dire... que je... ne vais pas mourir maintenant ?"
L35_1.m_Talk_FRA = L36_1
