L46_1 = "선생님은 모르는 게 없는 신기한 사람이었어요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "先生は何でも知っている不思議な人でした。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "The Teacher seemed to know everything about the world,"
L45_1.m_Talk_ENG = L46_1
L46_1 = "老師可是個無所不知、很不可思議的人。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "คุณครูดูจะรู้ทุกอย่างเกี่ยวกับโลกใบนี้"
L45_1.m_Talk_THA = L46_1
L46_1 = "Giáo Viên dường như biết tất cả mọi thứ về thế giới này,"
L45_1.m_Talk_VTN = L46_1
L46_1 = "老师可是个无所不知的人哦。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Es war, als wüsste der Lehrer alles über die Welt …"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Le Professeur semblait tout connaître du monde..."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "COUNTERCASE_GAEUN_NORMAL_3@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 31353
L46_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "내가 궁금한 게 생기면 뭐든 알려 주셨죠."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "私が知りたいことは何でも教えてくれたんです。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "and taught me anything I was curious about."
L46_1.m_Talk_ENG = L47_1
L47_1 = "如果我有什麼好奇的事，老師都會告訴我。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "และสอนสิ่งที่ฉันอยากรู้"
L46_1.m_Talk_THA = L47_1
L47_1 = "và dạy cho tôi bất cứ điều gì làm tôi tò mò."
L46_1.m_Talk_VTN = L47_1
L47_1 = "如果有什么好奇的事，老师都会一一解答。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "und als wüsste er Antworten auf all meine Fragen."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Et il m'a appris tout ce que je voulais savoir."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
