L3_1 = "오, 잘 익혔구나. 솜씨가 좋은걸."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "おお、いい焼き加減だ。器用なんだね。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Oh, that's perfect. You're pretty good at this."
L2_1.m_Talk_ENG = L3_1
L3_1 = "哦，做得很好啊，手藝不錯。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "อ๊ะ เยี่ยมเลย เธอนี่เก่งเรื่องนี้นะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ồ, thật hoàn hảo. Bạn khá giỏi trong việc này đấy."
L2_1.m_Talk_VTN = L3_1
L3_1 = "哦，做得很好啊。手艺不错。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Oh, das ist perfekt. Du bist wirklich gut darin."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Oh, c'est parfait. Tu es vraiment douée."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "COUNTERCASE_GAEUN_NORMAL_3@103#Talk"
