L4_1 = "ADMIN_COFFIN_NULL_QM"
L3_1.m_CharStrID = L4_1
L4_1 = "혹시 요리 배운 적 있니?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "ひょっとして料理を習ったことがあるのか？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Have you ever learned to cook?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "妳該不會有學過料理嗎？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เคยหัดทำอาหารมั้ย?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Bạn đã từng học nấu ăn rồi à?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "难道你有学过料理吗？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Hast du je gelernt, zu kochen?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Tu savais déjà cuisiner ?"
L3_1.m_Talk_FRA = L4_1
