L5_1 = "COUNTERCASE_GAEUN_NORMAL_3@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 31353
