L5_1 = "아니. 오늘이 처음이야."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "ううん。今日が初めて。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "No. This is the first time."
L4_1.m_Talk_ENG = L5_1
L5_1 = "沒有，我今天是第一次做。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ไม่ค่ะ นี่ครั้งแรก"
L4_1.m_Talk_THA = L5_1
L5_1 = "Không. Đây là lần đầu tiên đấy."
L4_1.m_Talk_VTN = L5_1
L5_1 = "没有，今天是第一次。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Nein. Das ist das erste Mal."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Non, c'est la première fois."
L4_1.m_Talk_FRA = L5_1
