L6_1 = "COUNTERCASE_GAEUN_NORMAL_3@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 31353
L5_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L5_1.m_Pos = "C"
L6_1 = "손은 괜찮아? 아까 시범 보여 주려다 데일 뻔했잖아."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "手は大丈夫？　さっきお手本を見せようとして、やけどするところだったでしょ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "How's your hand? You almost burned yourself trying to show me how to start a fire."
L5_1.m_Talk_ENG = L6_1
L6_1 = "您的手沒事吧？剛才是不是為了示範給我看差點燙傷了？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "มือเป็นไงบ้างคะ? คุณเกือบเผาตัวเองตอนจุดไฟแล้วนะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tay anh sao rồi? Suýt nữa thì anh đã tự đốt mình khi cố gắng chỉ cho tôi cách nhóm lửa đấy."
L5_1.m_Talk_VTN = L6_1
L6_1 = "手没事吧？刚刚是不是为了给我做示范差点烫伤了？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wie geht es deiner Hand? Du hast dich fast verbrannt, um mir zu zeigen, wie man Feuer macht."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Comment va votre main ? Vous avez failli vous brûler en voulant me montrer comment allumer un feu."
L5_1.m_Talk_FRA = L6_1
