L8_1 = "COUNTERCASE_GAEUN_NORMAL_3@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 31353
L7_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "ADMIN_COFFIN_NULL_QM"
L7_1.m_CharStrID = L8_1
L8_1 = "하하, 이론은 잘 알아도 실제로 하는 건 좀 어려워서 말이야."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "ははっ、頭ではわかっていても実際やるのは難しくてね。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Hah hah, I knew the theory behind it, but it's a lot harder than it looks."
L7_1.m_Talk_ENG = L8_1
L8_1 = "哈哈，就算知道理論，實際做起來卻有點難呢。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ฮ่าๆ ฉันเข้าใจวิธีจุดไฟนะ แต่พอทำจริงแล้วมันยาก"
L7_1.m_Talk_THA = L8_1
L8_1 = "Ha ha, tôi biết lý thuyết, nhưng đúng là khó hơn nhiều so với hình ảnh mà tôi xem."
L7_1.m_Talk_VTN = L8_1
L8_1 = "哈哈，看着容易做着难啊。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Haha, ich weiß, wie es theoretisch geht, aber es ist viel schwerer, als ich dachte."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Ha ha, je sais comment faire en théorie, mais c'est beaucoup plus difficile qu'il n'y paraît."
L7_1.m_Talk_FRA = L8_1
