L9_1 = "COUNTERCASE_GAEUN_NORMAL_3@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 31353
L8_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "그런데 선생님은 이 나라에 왜 왔어?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ところで、先生はどうしてこの国に来たの？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "So what are you doing in this country?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "不過老師為什麼會來這個國家？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แล้วคุณมาทำอะไรที่ประเทศนี้คะ?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Vậy anh đang làm gì ở đất nước này thế?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "不过老师为什么会来这个国家？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Also was machst du in diesem Land?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Qu'est-ce que vous faites dans ce pays ?"
L8_1.m_Talk_FRA = L9_1
