L11_1 = "COUNTERCASE_GAEUN_NORMAL_3@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 31353
L10_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "ADMIN_COFFIN_NULL_QM"
L10_1.m_CharStrID = L11_1
L11_1 = "흐음...... 내가 가진 특별한 컴퓨터에 필요한 부품이 여기 있다고 해서......"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ふむ……私の特別なコンピューターに必要な部品がここにあると聞いて……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Hmm... I was told the component required for my very special computer would be here..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "嗯……因為我有個很特別的電腦，它需要的一個零件在這個國家……"
L10_1.m_Talk_TWN = L11_1
L11_1 = "อืมม... มีคนบอกฉันว่าชิ้นส่วนที่จำเป็นต้องคอมพิวเตอร์พิเศษของฉันจะอยู่ที่นี่..."
L10_1.m_Talk_THA = L11_1
L11_1 = "Hmm... Tôi được thông báo là thành phần cần thiết cho chiếc máy tính rất đặc biệt của tôi sẽ ở đây..."
L10_1.m_Talk_VTN = L11_1
L11_1 = "哼嗯……因为我有个特殊的电脑，其中需要的一个零件在这个国家……"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Hmm … Man hat mir gesagt, dass die Teile für meinen Spezialcomputer hier zu finden seien …"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Hmm... On m'a dit que la pièce dont j'avais besoin pour mon ordinateur spécial était ici..."
L10_1.m_Talk_FRA = L11_1
