L13_1 = "COUNTERCASE_GAEUN_NORMAL_3@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 31353
L12_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "ADMIN_COFFIN_NULL_QM"
L12_1.m_CharStrID = L13_1
L13_1 = "아니, 그냥 보물이 있다는 말을 듣고 찾으러 왔단다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "いや、ただ宝物があるという話を聞いて探しにきたんだ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I mean, they just said there's a treasure here. So I came looking for it."
L12_1.m_Talk_ENG = L13_1
L13_1 = "不，妳就當我是來找寶藏的好了。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "พวกเขาบอกว่าที่นี่มีขุมทรัพย์ ฉันเลยมาหาดู"
L12_1.m_Talk_THA = L13_1
L13_1 = "Ý tôi là, họ nói có một kho báu ở đây. Vì vậy, tôi đến để tìm nó."
L12_1.m_Talk_VTN = L13_1
L13_1 = "不，你就当我是来找宝藏好了。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Also, ich meine, es soll hier einen Schatz geben. Also bin ich gekommen, um ihn zu suchen."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Enfin, on m'a dit qu'il y avait un trésor ici, et je suis venu le chercher."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "COUNTERCASE_GAEUN_NORMAL_3@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 31353
L13_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "그럼 보물은 찾았어? 혹시 날 구하느라 잃어 버렸다거나......"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "それで、宝物は見つかった？　まさか私を助けようとして失くしたとか……"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Did you find the treasure? Or did you lose it because you had to save me?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "那您找到寶藏了嗎？會不會因為救我所以沒有……"
L13_1.m_Talk_TWN = L14_1
L14_1 = "แล้วเจอขุมทรัพย์มั้ยคะ? หรือทำหายไปเพราะต้องช่วยหนู?"
L13_1.m_Talk_THA = L14_1
L14_1 = "Anh đã tìm thấy kho báu chưa? Hay anh đã làm mất nó vì phải cứu tôi?"
L13_1.m_Talk_VTN = L14_1
L14_1 = "找到宝藏了吗？会不会因为救我所以丢……"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Hast du den Schatz gefunden? Oder hast du ihn verloren, weil du mich retten musstest?"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Vous avez trouvé ce trésor ? Ou vous l'avez perdu à cause de moi ?"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
