L16_1 = "COUNTERCASE_GAEUN_NORMAL_3@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 31353
L15_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "ADMIN_COFFIN_NULL_QM"
L15_1.m_CharStrID = L16_1
L16_1 = "하하. 아쉽게도 헛소문이었던 것 같아."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "はは。残念ながらただの噂だったみたいだ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Hah hah. Unfortunately, I guess I was just chasing a rumor."
L15_1.m_Talk_ENG = L16_1
L16_1 = "哈哈。很遺憾，寶藏好像是個謠言。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ฮ่าๆ น่าเสียดายที่ฉันแค่ไล่ตามข่าวลือน่ะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Ha ha. Thật không may, tôi đoán mình chỉ đang theo đuổi một lời đồn nhảm."
L15_1.m_Talk_VTN = L16_1
L16_1 = "哈哈。很遗憾，那好像是个谣言。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Haha. Ich fürchte, dass ich bedauerlicherweise nur ein Gerücht verfolgt habe."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Ha ha. Malheureusement, il semble que je courais après une rumeur infondée."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "COUNTERCASE_GAEUN_NORMAL_3@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 31353
L16_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "ADMIN_COFFIN_NULL_QM"
L16_1.m_CharStrID = L17_1
L17_1 = "그래도 이렇게 똑똑한 학생이 생겼으니 다른 보물을 찾았다고 해야겠지."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "でもこんなに賢い生徒と会えたのだから、別の宝物を見つけたと言うべきだろうな。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Still, I guess I found a treasure after all. You're one smart kid."
L16_1.m_Talk_ENG = L17_1
L17_1 = "但能得到一個這麼聰明的學生，也算是找到了另一種寶藏呢。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แต่ฉันว่าฉันก็ได้พบขุมทรัพย์นะ เธอเป็นเด็กฉลาด"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tuy nhiên, tôi đoán suy cho cùng mình đã tìm thấy một kho báu. Bạn là một đứa trẻ thông minh."
L16_1.m_Talk_VTN = L17_1
L17_1 = "但是能有个这么聪明的学生，也能算是找到了另一种宝藏。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Aber ich glaube, ich habe trotzdem einen Schatz gefunden. Du bist ein sehr schlaues Kind."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Néanmoins, il semblerait que j'aie bien trouvé un trésor. Tu es une petite futée."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "COUNTERCASE_GAEUN_NORMAL_3@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 31353
L17_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L17_1.m_Pos = "C"
L18_1 = "......그럼, 머리 쓰다듬어 줘."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "……それじゃあ、頭をなでて。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Then pat me on my head."
L17_1.m_Talk_ENG = L18_1
L18_1 = "……那就，摸摸我的頭。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "งั้นก็ลูบหัวหนูสิ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Vậy thì xoa đầu tôi đi."
L17_1.m_Talk_VTN = L18_1
L18_1 = "……那，就摸摸我的头。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Dann streichel mir den Kopf."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Alors caressez-moi la tête."
L17_1.m_Talk_FRA = L18_1
