L21_1 = "COUNTERCASE_GAEUN_NORMAL_3@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 31353
L20_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L20_1.m_Pos = "C"
L21_1 = "사람들은 보물이 생기면 소중하게 쓰다듬잖아."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "人は宝物ができると大事になでるでしょう？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "People like to pat their precious treasures."
L20_1.m_Talk_ENG = L21_1
L21_1 = "人們獲得寶物時，不是會很珍惜地撫摸它們嗎？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "คนชอบลูบสิ่งล้ำค่าของตัวเอง"
L20_1.m_Talk_THA = L21_1
L21_1 = "Mọi người thích vỗ về kho báu quý giá của họ."
L20_1.m_Talk_VTN = L21_1
L21_1 = "人们有了宝物时，不是会很珍惜地抚摸它们吗？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ja, die Leute streicheln gerne über ihre Schätze."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Les gens caressent toujours leurs trésors."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "COUNTERCASE_GAEUN_NORMAL_3@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 31353
L21_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "나도 보물이니까, 쓰다듬어 줘."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "私も宝物だから、なでてちょうだい。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Since I'm your treasure, pat me."
L21_1.m_Talk_ENG = L22_1
L22_1 = "因為我也是寶物，所以請摸摸我的頭。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ในเมื่อหนูเป็นสมบัติของคุณ งั้นก็ลูบหนูสิ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Vì tôi là kho báu của anh, nên hãy xoa đầu tôi."
L21_1.m_Talk_VTN = L22_1
L22_1 = "我也是宝物，所以摸摸我的头。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Und wenn ich dein Schatz bin, musst du mich auch streicheln."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Alors si je suis votre trésor, vous devez le faire aussi."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
