L26_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE"
L27_1 = "선생님은 약한 사람이었습니다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "先生は弱い人でした。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "The Teacher wasn't very strong,"
L26_1.m_Talk_ENG = L27_1
L27_1 = "老師是個體力非常弱的人。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "คุณครูไม่ค่อยแข็งแรงนัก"
L26_1.m_Talk_THA = L27_1
L27_1 = "Giáo Viên không mạnh mẽ cho lắm,"
L26_1.m_Talk_VTN = L27_1
L27_1 = "老师是个体力非常弱的人。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Der Lehrer war nicht gerade stark:"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Le Professeur n'était pas très fort."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "COUNTERCASE_GAEUN_NORMAL_3@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 31353
L27_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "나보다 오래 못 달리고, 햇빛을 쬐면 금방 어지러워했어요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "私よりも長く走れず、日に当たるとすぐにめまいを起こしました。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "unable to run as long as I could, getting dizzy under the sun."
L27_1.m_Talk_ENG = L28_1
L28_1 = "不但跑得沒我久，一曬到太陽還會馬上暈過去。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "วิ่งนานๆ เหมือนฉันไม่ได้ และมักตาลายใต้แสงอาทิตย์"
L27_1.m_Talk_THA = L28_1
L28_1 = "không thể chạy lâu như tôi, dễ bị chóng mặt dưới ánh mặt trời."
L27_1.m_Talk_VTN = L28_1
L28_1 = "不仅跑得没我久，而且晒会太阳就会马上晕过去。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Er konnte nicht so weit laufen wie ich und in der Sonne wurde ihm schnell schwindelig."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Il ne pouvait pas courir aussi longtemps que moi et il avait des vertiges au soleil."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "COUNTERCASE_GAEUN_NORMAL_3@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 31353
L28_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "하지만 선생님께 배웠어요."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "でも、先生から学んだんです。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "But I learned a lot from Teacher."
L28_1.m_Talk_ENG = L29_1
L29_1 = "但是我從老師那裡學到了一件事……"
L28_1.m_Talk_TWN = L29_1
L29_1 = "แต่ฉันเรียนรู้อะไรมากมายจากคุณครู"
L28_1.m_Talk_THA = L29_1
L29_1 = "Nhưng tôi đã học được rất nhiều điều từ Giáo Viên."
L28_1.m_Talk_VTN = L29_1
L29_1 = "但是我从老师那里学到了，"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Aber ich habe viel vom Lehrer gelernt."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Mais il m'a beaucoup appris."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "COUNTERCASE_GAEUN_NORMAL_3@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 31353
L29_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "나도 다른 사람에게 도움이 될 수 있다는 걸."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "私も他の人の役に立てるということを。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I learned that I could help someone else too."
L29_1.m_Talk_ENG = L30_1
L30_1 = "那就是我也有能力幫助別人。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันเรียนรู้ว่าฉันเองก็ช่วยคนอื่นได้"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi học được rằng mình cũng có thể giúp đỡ người khác."
L29_1.m_Talk_VTN = L30_1
L30_1 = "我也有能力帮助别人。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Zum Beispiel, dass auch ich anderen helfen kann."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Il m'a appris que je pouvais aider quelqu'un, moi aussi."
L29_1.m_Talk_FRA = L30_1
