L32_1.m_Crash = 20
L33_1 = "선생님, 또 넘어질 뻔했어."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "先生、また倒れるところだったよ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "You almost tripped again, Teacher."
L32_1.m_Talk_ENG = L33_1
L33_1 = "老師，您又差點摔倒了。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เกือบล้มอีกแล้วนะคะ คุณครู"
L32_1.m_Talk_THA = L33_1
L33_1 = "Anh lại suýt ngã nữa đấy, Giáo Viên."
L32_1.m_Talk_VTN = L33_1
L33_1 = "老师，你又差点摔倒了。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Du bist schon wieder fast gestolpert, Lehrer."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Vous avez encore failli tomber, Professeur."
L32_1.m_Talk_FRA = L33_1
