L35_1 = "ADMIN_COFFIN_NULL_QM"
L34_1.m_CharStrID = L35_1
L35_1 = "하하, 이거 면목이 없구나. 나도 몸이 튼튼한 편은 아니라서."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "はは、申し訳ない。私も体が丈夫なほうではなくてね。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Hah hah. This is embarrassing. I'm not very fit either."
L34_1.m_Talk_ENG = L35_1
L35_1 = "哈哈，真丟臉啊，畢竟我的身體沒有很強壯。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ฮ่าๆ น่าอายจัง ฉันไม่ค่อยแข็งแรง"
L34_1.m_Talk_THA = L35_1
L35_1 = "Ha ha. Thật đáng xấu hổ. Tôi cũng không còn sức nữa."
L34_1.m_Talk_VTN = L35_1
L35_1 = "哈哈，真丢脸啊。我的身体也不算很结实。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Haha, oh, das ist peinlich. Ich bin wirklich nicht gerade in Topform."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ha ha, c'est gênant. Je ne suis pas très en forme."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "COUNTERCASE_GAEUN_NORMAL_3@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 31353
L35_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_IDLE"
L35_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "내, 내가 부축해 줄게. 이쪽으로 기대."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "わ、私が支えてあげる。こっちに寄りかかって。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "L-let me help you walk. Lean on me."
L35_1.m_Talk_ENG = L36_1
L36_1 = "我、我來扶著您，您靠在這裡。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ดะ-เดี๋ยวหนูช่วยคุณเดินนะคะ พิงหนูสิ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Đ-để tôi giúp anh đi bộ. Tựa vào người tôi này."
L35_1.m_Talk_VTN = L36_1
L36_1 = "我，我来扶着您。靠在这里。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "L-lass mich dir helfen. Stütz’ dich auf mich."
L35_1.m_Talk_DEU = L36_1
L36_1 = "L-Laissez-moi vous aider. Vous pouvez vous appuyer sur moi."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 31353
L36_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L36_1.m_bWaitClick = false
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L36_1.m_Pos = "C_D"
L37_1 = {}
L38_1 = "COUNTERCASE_GAEUN_NORMAL_3@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 31353
L37_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "ADMIN_COFFIN_NULL_QM"
L37_1.m_CharStrID = L38_1
L38_1 = "그래도 어른 체면이 있지. 아이에게 기대면 쓰나."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "いや、大人としてそれは無理だ。子供に頼るなんてできない。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Hey, but I'm a responsible adult. I shouldn't have to rely on a child."
L37_1.m_Talk_ENG = L38_1
L38_1 = "我也有身為大人的面子啊，怎麼能靠著一個孩子呢？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "นี่ ฉันเป็นผู้ใหญ่ที่ดูแลตัวเองได้นะ ฉันไม่ควรต้องพึ่งพาเด็ก"
L37_1.m_Talk_THA = L38_1
L38_1 = "Này, nhưng tôi là một người lớn có trách nhiệm. Tôi không cần phải dựa vào một đứa trẻ."
L37_1.m_Talk_VTN = L38_1
L38_1 = "我也有作为大人的面子啊，怎么能靠着孩子呢。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Hey, warte mal. Ich bin ein Erwachsener. Ich kann mich doch nicht auf ein Kind stützen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Je suis un adulte responsable, tout de même. Je ne devrais pas avoir à compter sur une enfant."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "COUNTERCASE_GAEUN_NORMAL_3@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 31353
L38_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "괜찮아. 선생님이 아니었으면...... 난 그때 죽었을 거야."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "大丈夫。先生がいなかったら……私はあの時死んでいたはずだから。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "It’s okay. If it weren't for you... I'd be dead already."
L38_1.m_Talk_ENG = L39_1
L39_1 = "沒關係。如果不是老師救了我……我早就死了。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ไม่เป็นไรค่ะ ถ้าไม่ได้คุณ... หนูคงตายไปแล้ว"
L38_1.m_Talk_THA = L39_1
L39_1 = "Không sao đâu. Nếu không có anh... tôi đã chết rồi."
L38_1.m_Talk_VTN = L39_1
L39_1 = "没关系，如果不是老师救了我……我早就死了。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ist schon in Ordnung. Ohne dich … wäre ich längst tot."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Ce n'est pas grave. Sans vous... je serais déjà morte."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "COUNTERCASE_GAEUN_NORMAL_3@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 31353
L39_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L39_1.m_Pos = "C"
L40_1 = "도움을 받으면 갚아야 한다고 했잖아. 난 선생님이 가르쳐 준 대로 할래."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "助けてもらった恩は返さなきゃいけないって言ったでしょ。私は先生が教えてくれたとおりにする。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "You said I should pay people who help me back. I'll do as you taught me."
L39_1.m_Talk_ENG = L40_1
L40_1 = "老師不是教過我要知恩圖報嗎？我會按照老師教的去做。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "คุณบอกว่าเราควรตอบแทนคนที่ช่วยเรา หนูก็จะทำอย่างที่คุณสอนค่ะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Anh nói tôi nên trả ơn cho những người đã giúp đỡ mình. Tôi sẽ làm như lời anh đã dạy."
L39_1.m_Talk_VTN = L40_1
L40_1 = "老师不是教过我要知恩图报吗？我要按照老师教的做。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Du hast mir beigebracht, gut zu den Menschen zu sein, die gut zu mir waren. Ich befolge nur deine Lektionen."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Vous avez dit que je devais rendre la pareille aux gens qui m'aident. Je fais ce que vous m'avez appris."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "COUNTERCASE_GAEUN_NORMAL_3@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 31353
L40_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L40_1.m_Pos = "C"
L41_1 = "그러니까...... 이 정도는 아무것도 아니야."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "だから……これくらいどうってことない。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "So... This is nothing compared to what you've done for me."
L40_1.m_Talk_ENG = L41_1
L41_1 = "而且……這點小事也不算什麼。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "แล้วก็... เท่านี้ยังเทียบกับสิ่งที่คุณทำเพื่อหนูไม่ได้เลยค่ะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Cho nên là... Chuyện này không là gì so với những chuyện anh đã làm cho tôi."
L40_1.m_Talk_VTN = L41_1
L41_1 = "所以……而且这种程度算不上什么。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Und das … ist nichts im Vergleich zu dem, was du für mich getan hast."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Et puis... Ce n'est rien comparé à ce que vous avez fait pour moi."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
