L44_1 = "COUNTERCASE_GAEUN_NORMAL_3@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 31353
L43_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "ADMIN_COFFIN_NULL_QM"
L43_1.m_CharStrID = L44_1
L44_1 = "그래, 고맙구나. 그럼 조금만 기댈게."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "そうか、ありがとう。なら少しだけ甘えるよ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I see... Thank you. Then I guess I'll lean on you just a little."
L43_1.m_Talk_ENG = L44_1
L44_1 = "是嗎，謝謝妳。那就讓我靠一會吧。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เข้าใจแล้ว... ขอบคุณนะ งั้นฉันขอพิงเธอนิดนึงแล้วกัน"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi hiểu rồi, cảm ơn bạn. Vậy thì tôi đoán mình sẽ dựa vào bạn, chỉ một chút thôi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "是吗，谢谢你。那就让我靠一会吧。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Verstehe. Danke. Dann stütze ich mich mal ein bisschen ab."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je vois... Merci. Je vais me reposer un peu sur toi, alors."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
