L47_1 = "COUNTERCASE_GAEUN_NORMAL_3@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 31353
L46_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE"
L47_1 = "힘들고, 위험할 때도 있었지만 늘 기뻤습니다."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "大変で危険な時もありましたが、いつも幸せでした。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Things got tough and even dangerous at times, but I was always happy."
L46_1.m_Talk_ENG = L47_1
L47_1 = "雖然也有很辛苦、很危險的時候，但我過得很開心。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "บางครั้งอะไรๆ ก็ยากลำบากและอันตรายบ้าง แต่ฉันมีความสุขเสมอ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Đôi khi mọi chuyện trở nên khó khăn và thậm chí là nguy hiểm, nhưng tôi luôn vui vẻ."
L46_1.m_Talk_VTN = L47_1
L47_1 = "虽然有时候很累很危险，但我过得很开心。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Manchmal waren die Zeiten hart, manchmal sogar gefährlich – aber ich war immer glücklich."
L46_1.m_Talk_DEU = L47_1
L47_1 = "La vie était dure et parfois dangereuse, mais j'étais toujours heureuse."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "COUNTERCASE_GAEUN_NORMAL_3@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 31353
L47_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "선생님과 함께였으니까."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "先生と一緒だったから。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Because I was with my Teacher."
L47_1.m_Talk_ENG = L48_1
L48_1 = "因為我跟老師在一起。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เพราะฉันได้อยู่กับคุณครูของฉัน"
L47_1.m_Talk_THA = L48_1
L48_1 = "Bởi vì tôi đã có Giáo Viên của mình."
L47_1.m_Talk_VTN = L48_1
L48_1 = "因为老师和我在一起。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Denn ich war beim Lehrer."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Parce que j'étais avec mon Professeur."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
