L8_1 = "COUNTERCASE_GAEUN_NORMAL_3@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 31353
L7_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L7_1.m_bWaitClick = true
