L7_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L7_1.m_Pos = "C"
L7_1.m_Crash = 15
L8_1 = "응. 모르는 것도 없고, 요리하는 법도 가르쳐 주고, 죽을 뻔했을 때도 구해 주고, 그리고...... 그리고 또......"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "うん。何でも知ってるし、料理も教えてくれるし、死にそうなところを助けてくれたし、あと……それから……"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Yeah. You know everything. You even taught me how to cook, and saved my life. And... and..."
L7_1.m_Talk_ENG = L8_1
L8_1 = "嗯。老師沒有不知道的事情，不但教我做料理，還在我快死掉的時候救了我，而且……還有……"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ใช่ คุณรู้ทุกเรื่องเลย แถมยังสอนหนูทำอาหารและช่วยชีวิตหนูด้วย แล้วก็... แล้วก็..."
L7_1.m_Talk_THA = L8_1
L8_1 = "Vâng. Anh biết tất cả mọi thứ. Thậm chí anh còn dạy tôi cách nấu ăn, và đã cứu mạng tôi. Và... và..."
L7_1.m_Talk_VTN = L8_1
L8_1 = "嗯，老师没有不知道的事，教我做料理，在我差点死掉的时候救了我，而且……还有……"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ja. Du weißt alles. Du hast mir sogar beigebracht, zu kochen, du hast mir das Leben gerettet und … und …"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Oui. Vous savez tout, vous m'avez appris à cuisiner et sauvé la vie, et... et..."
L7_1.m_Talk_FRA = L8_1
