L10_1.m_CharStrID = L11_1
L11_1 = "같이 다니면서 봤지? 선생님은 서툰 점이 많은 사람이야."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "一緒に過ごす間に見ただろ？　先生は不器用な人なんだ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Haven't you seen what I'm like? I can be very clumsy too."
L10_1.m_Talk_ENG = L11_1
L11_1 = "妳也看到了吧？老師是個有很多缺點的人。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ไม่เห็นเหรอว่าฉันเป็นยังไง? ฉันก็ซุ่มซ่ามเอามากๆ นะ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Bạn chưa thấy tôi như thế nào sao? Tôi cũng có những lúc rất vụng về."
L10_1.m_Talk_VTN = L11_1
L11_1 = "你也看到了，老师是个有很多缺点的人。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ist dir nicht aufgefallen, wie ungeschickt ich oft bin?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Tu as bien vu comment j'étais, non ? Je peux être très maladroit."
L10_1.m_Talk_FRA = L11_1
