L14_1 = "하, 하지만 포기 안 했지? 선생님은 끈기 있는 사람이잖아?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "で、でも諦めなかったでしょ？　先生は粘り強い人だよね？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "B-but you never gave up, have you? You're a tenacious person, right?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "但、但是老師沒有放棄吧？老師是個非常堅強的人吧？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ตะ-แต่คุณก็ไม่เคยยอมแพ้ไม่ใช่เหรอคะ? คุณเป็นคนทรหด ถูกมั้ย?"
L13_1.m_Talk_THA = L14_1
L14_1 = "N-nhưng anh chưa bao giờ bỏ cuộc, đúng không? Anh là một người ngoan cường mà?"
L13_1.m_Talk_VTN = L14_1
L14_1 = "但，但老师从来没有放弃过，对吧？老师是个非常坚强的人吧？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "A-aber aufgegeben hast du nie, oder? Du bist doch ein Mensch mit viel Ausdauer!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Mais vous n'avez jamais renoncé, pas vrai ? Vous êtes quelqu'un de tenace, non ?"
L13_1.m_Talk_FRA = L14_1
