L33_1 = "知らなかったんだね。実は少し寂しかったよ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Oh, so you didn't know. Actually, I've been a bit disappointed."
L32_1.m_Talk_ENG = L33_1
L33_1 = "原來妳都不知道啊，事實上還有點寂寞的樣子呢。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "อ้าว นี่ไม่รู้ตัวเหรอ ฉันผิดหวังนิดหน่อยนะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Ồ, vậy là bạn không biết. Thực ra thì tôi hơi thất vọng một chút đấy."
L32_1.m_Talk_VTN = L33_1
L33_1 = "原来你都不知道啊，事实上还是有点寂寞的。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Oh, ist dir wohl gar nicht aufgefallen. Ehrlich gesagt war ich schon etwas enttäuscht."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Oh, tu ne l'avais pas remarqué. À vrai dire, j'étais un peu déçu."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "COUNTERCASE_GAEUN_NORMAL_3@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 31353
L33_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "모...... 몰랐어. 선생님 앞에선 매일 웃고 있는 줄 알았는데."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "し……知らなかった。先生の前ではいつも笑ってるんだと思ってたのに。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I... I had no idea. I thought I'd be smiling in front of you all day."
L33_1.m_Talk_ENG = L34_1
L34_1 = "我……我不知道，我以為自己每天都是帶著笑容面對老師的。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "หนู... หนูไม่รู้เลยค่ะ หนูนึกว่าตัวเองยิ้มต่อหน้าคุณทั้งวัน"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tôi... tôi không biết nữa. Tôi tưởng mình cứ mỉm cười trước mặt anh cả ngày rồi cơ chứ."
L33_1.m_Talk_VTN = L34_1
L34_1 = "我……我不知道。我以为自己每天都是带着笑容面对老师的。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich … ich hatte ja keine Ahnung. Ich dachte, ich würde den ganzen Tag lächelnd umherlaufen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je... Je ne savais pas. Je pensais que je vous souriais toute la journée."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "COUNTERCASE_GAEUN_NORMAL_3@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 31353
L34_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "UNIT_LAUGH"
L34_1.m_Face = L35_1
L34_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = 40
L34_1.m_Crash = L35_1
L35_1 = "그럼 앞으로는 계속 웃고 다닐래. 자."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "じゃあこれからはずっと笑顔でいるね。ほら。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Okay, then. I'll keep smiling from now on. See?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "那我以後要一直笑下去，像這樣。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "งั้นก็โอเค จากนี้หนูจะยิ้มนะคะ เห็นมั้ย?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Được rồi. Tôi sẽ tiếp tục mỉm cười từ bây giờ. Sao nào?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "那我以后要一直笑下去，像这样。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Na gut. Ab jetzt werde ich weiter lächeln. Siehst du?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "C'est décidé. À partir de maintenant, je sourirai tout le temps. Vous voyez ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
