L37_1 = "COUNTERCASE_GAEUN_NORMAL_3@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 31353
L36_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
