L36_1.m_fWaitTime = 0
L37_1 = "ADMIN_COFFIN_NULL_QM"
L36_1.m_CharStrID = L37_1
L37_1 = "그렇다고 손가락으로 당겨서까지 억지로 웃을 필요는 없단다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "だからって、指で引っ張ってまで無理やり笑顔を作る必要はない。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "You don't have to pull your mouth back and force a smile like that."
L36_1.m_Talk_ENG = L37_1
L37_1 = "話是這麼說，也沒必要用手指拉著嘴角，勉強自己笑出來。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เธอไม่ต้องฉีกยิ้มแห้งๆ แบบนั้นก็ได้"
L36_1.m_Talk_THA = L37_1
L37_1 = "Bạn không cần phải cố gắng nở một nụ cười như thế."
L36_1.m_Talk_VTN = L37_1
L37_1 = "不过没必要硬逼着自己笑。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Das sieht ziemlich gezwungen aus."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Tu n'as pas besoin de t'étirer les lèvres et de te forcer à sourire ainsi."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "COUNTERCASE_GAEUN_NORMAL_3@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 31353
L37_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "ADMIN_COFFIN_NULL_QM"
L37_1.m_CharStrID = L38_1
L38_1 = "언젠가는 그러지 않아도 자연스럽게 웃을 수 있을 거야."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "いつかはそうしなくても、自然と笑える日がくるだろう。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I'm sure you'll learn to smile naturally one day."
L37_1.m_Talk_ENG = L38_1
L38_1 = "總有一天，妳也能自然地笑出來的。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ฉันมั่นใจว่าสักวันเธอจะยิ้มได้อย่างเป็นธรรมชาติเอง"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi chắc rằng một ngày nào đó bạn sẽ học cách mỉm cười tự nhiên."
L37_1.m_Talk_VTN = L38_1
L38_1 = "你总有一天也能自然地笑出来。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Sicher wirst du eines Tages lernen, wie ein natürliches Lächeln aussieht."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Je suis sûr que tu apprendras à sourire naturellement, un jour."
L37_1.m_Talk_FRA = L38_1
