L40_1 = "선생님, 나도 소원이 생겼어."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "先生、私にも願い事ができた。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I've got a wish too, Teacher."
L39_1.m_Talk_ENG = L40_1
L40_1 = "老師，我也有願望了。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "หนูก็มีความปรารถนาเหมือนกันค่ะ คุณครู"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tôi cũng có một điều ước, Giáo Viên."
L39_1.m_Talk_VTN = L40_1
L40_1 = "老师，我也有愿望了。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ich habe auch einen Wunsch, Lehrer."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Moi aussi j'ai un rêve, Professeur."
