L42_1 = "ADMIN_COFFIN_NULL_QM"
L41_1.m_CharStrID = L42_1
L42_1 = "알고 있단다. 다음에 태어나면 평범한 삶을 살고 싶다고 했었나?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "知ってる。今度生まれ変わったら、平凡な人生を送りたいと言ってたっけ？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I'm aware. You said you wanted to live an ordinary life next time, right?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "我知道啊。妳說妳投胎轉世的話，想過平凡的生活吧。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ฉันรู้ เธอบอกว่าชาติหน้าอยากมีชีวิตปกติ ถูกมั้ย?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi biết. Bạn từng nói mình muốn sống một cuộc sống bình thường trong kiếp sau, phải không?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "我知道，如果投胎转世的话想过平凡的生活？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ich weiß. Du willst nächstes Mal ein gewöhnliches Leben führen, stimmts?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Je sais. Tu as dit que tu voulais que ta prochaine vie soit ordinaire, n'est-ce pas ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
