L43_1 = "그, 그거 말고. 이번엔 다른 소원이야."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "そ、そうじゃなくて。今回は違うの。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "N-not that. A different wish."
L42_1.m_Talk_ENG = L43_1
L43_1 = "不，不是那個，這次是別的願望。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "มะ-ไม่ใช่อันนั้นสิ อีกความปรารถนาหนึ่ง"
L42_1.m_Talk_THA = L43_1
L43_1 = "K-không phải vậy. Một điều ước khác."
L42_1.m_Talk_VTN = L43_1
L43_1 = "不，不是那个。这次是别的愿望。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "N-nein. Einen anderen Wunsch."
L42_1.m_Talk_DEU = L43_1
L43_1 = "N-Non, pas celui-là. Un autre rêve."
L42_1.m_Talk_FRA = L43_1
