L45_1 = "ADMIN_COFFIN_NULL_QM"
L44_1.m_CharStrID = L45_1
L45_1 = "그래? 그럼 새로운 소원은 뭔데?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "そうか？　じゃあ、新しい願いは何だい？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Yeah? What is this new wish then?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "是嗎？那妳新的願望是什麼？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เหรอ? มันคืออะไรล่ะ?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Vậy ư? Điều ước mới này là gì thế?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "嗯？那新的愿望是什么？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Aha? Was ist denn dein neuer Wunsch?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Ah ? Et quel est ce nouveau rêve ?"
L44_1.m_Talk_FRA = L45_1
