L46_1 = "서, 선생님은 똑똑한데 몸도 약하고 실수도 많이 하니까......"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "せ、先生は賢いけど体も弱くて、失敗もたくさんするから……"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Y-you're smart, but you're clumsy and weak..."
L45_1.m_Talk_ENG = L46_1
L46_1 = "老、老師雖然很聰明，但是身體不太好，也經常失誤……"
L45_1.m_Talk_TWN = L46_1
L46_1 = "คะ-คุณฉลาดนะคะ แต่คุณซุ่มซ่ามและอ่อนแอ..."
L45_1.m_Talk_THA = L46_1
L46_1 = "A-anh thông minh, nhưng lại vụng về và yếu ớt..."
L45_1.m_Talk_VTN = L46_1
L46_1 = "老，老师虽然很聪明，但是身体不太好，也经常失误……"
L45_1.m_Talk_SCN = L46_1
L46_1 = "D-du bist klug, aber ungeschickt und schwach …"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Vous êtes intelligent, mais vous êtes aussi faible et maladroit..."
L45_1.m_Talk_FRA = L46_1
