L46_1.m_Pos = "C"
L47_1 = "선생님이 소원을 이룰 때까지......"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "先生が願いを叶えるまでは……"
L46_1.m_Talk_JPN = L47_1
L47_1 = "So until your wish comes true, I..."
L46_1.m_Talk_ENG = L47_1
L47_1 = "所以直到老師的願望實現的那天……"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ดังนั้น จนกว่าความปรารถนาของคุณจะเป็นจริง หนู..."
L46_1.m_Talk_THA = L47_1
L47_1 = "Vì vậy, cho đến khi điều ước của anh thành hiện thực, tôi..."
L46_1.m_Talk_VTN = L47_1
L47_1 = "所以直到老师的愿望实现的那天……"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Deshalb will ich, bis dein Wunsch in Erfüllung geht …"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Alors, jusqu'à ce que vous réalisiez votre rêve, je..."
L46_1.m_Talk_FRA = L47_1
