L4_1 = "COUNTERCASE_GAEUN_NORMAL_3@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 31353
L3_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "OFFICER_ADMIN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "그로니아에서 샤레이드까지 걸어오셨다고요?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "グロニアからシャレードまで歩いて来たんですか？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "You walked all the way from Gronia to Charade?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "你說你是從葛羅尼亞走到了查雷德？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "คุณเดินจากโกรเนียมาถึงชาเรดเหรอ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Các bạn đã đi bộ từ Gronia đến Charade sao?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "你是说从格罗尼亚走到了查雷德？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Sie sind den ganzen Weg von Gronia nach Charade gelaufen?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Vous avez vraiment marché de Gronia à Charade ?"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "COUNTERCASE_GAEUN_NORMAL_3@204#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 204
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 31353
L4_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "OFFICER_ADMIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "그렇게 건강해 보이시지는 않는데...... 정말 고생하셨습니다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "そこまで丈夫な方には見えませんが……本当にご苦労様でした。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "You don't strike me as someone that fit... That must have been real tough."
L4_1.m_Talk_ENG = L5_1
L5_1 = "雖然你的健康狀況不像能走那麼遠的樣子……但真是辛苦你了。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "คุณดูไม่เหมือนคนที่จะแข็งแรงขนาดนั้นเลย... คงยากมากแน่ๆ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Với tôi nhìn anh không thực sự khỏe mạnh cho lắm... Hẳn là rất vất vả nhỉ."
L4_1.m_Talk_VTN = L5_1
L5_1 = "虽然健康状况看起来不像能走那么远……真的受苦了。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Sie wirken gar nicht so sportlich … Das muss echt anstrengend gewesen sein."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Vous n'avez pas l'air très en forme... Ça n'a pas dû être facile."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "COUNTERCASE_GAEUN_NORMAL_3@205#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 205
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 31353
L5_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "OFFICER_ADMIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "동행한 아이에 대해서는 일단 임시 의료 지원이 이루어질 거예요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "お連れの子供には、ひとまず臨時の医療支援が行われる予定です。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "As for the child accompanying you, we'll provide her with some initial medical care for now."
L5_1.m_Talk_ENG = L6_1
L6_1 = "我們會先對同行的孩子進行臨時的醫療支援。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ส่วนเด็กที่มากับคุณ เราจะตรวจร่างกายเธอเบื้องต้นก่อน"
L5_1.m_Talk_THA = L6_1
L6_1 = "Với đứa trẻ đi cùng anh, chúng tôi sẽ cung cấp cho bé một số chăm sóc y tế ban đầu."
L5_1.m_Talk_VTN = L6_1
L6_1 = "我们会先对同行的孩子进行临时医疗支援。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Das Kind, das Sie begleitet, werden wir grundlegend medizinisch versorgen."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Quant à l'enfant qui vous accompagne, nous allons lui fournir des soins d'urgence."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "COUNTERCASE_GAEUN_NORMAL_3@206#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 31353
L6_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "OFFICER_ADMIN_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "하지만 의료진들 얘기로는...... 시력이 완전히 회복될지는 장담하기 어렵다더군요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "しかし医師たちの話によると……視力が完全に回復するかは断言できないそうです。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "But according to the medical staff, they can't guarantee when her sight would be restored."
L6_1.m_Talk_ENG = L7_1
L7_1 = "然而根據醫療團隊的說法……無法保證她的視力能夠完全恢復。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "แต่เจ้าหน้าที่การแพทย์บอกว่า พวกเขารับประกันไม่ได้ว่าเธอจะกลับมามองเห็นอีกครั้ง"
L6_1.m_Talk_THA = L7_1
L7_1 = "Nhưng theo các nhân viên y tế, họ không thể đảm bảo thị lực của cô bé sẽ được phục hồi."
L6_1.m_Talk_VTN = L7_1
L7_1 = "但是根据医疗团队的说法……无法保证视力能够完全恢复。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Aber das Team kann nicht garantieren, ob und wann ihr Augenlicht zurückkehrt."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Mais d'après l'équipe médicale, on ne peut pas savoir quand elle retrouvera la vue."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
