L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C_D"
L8_1 = {}
L9_1 = "COUNTERCASE_GAEUN_NORMAL_3@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 31353
L8_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "ADMIN_COFFIN_NULL_QM"
L8_1.m_CharStrID = L9_1
L9_1 = "강한 아이입니다. 반드시 나을 수 있을 거에요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "強い子です。きっと治るはずです。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "She's a strong girl. I'm sure she'll recover."
L8_1.m_Talk_ENG = L9_1
L9_1 = "她是個堅強的孩子，一定都會好起來的。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เธอเป็นเด็กที่แข็งแกร่ง ผมมั่นใจว่าเธอจะหายดี"
L8_1.m_Talk_THA = L9_1
L9_1 = "Cô ấy là một cô gái mạnh mẽ. Tôi chắc rằng cô ấy sẽ bình phục."
L8_1.m_Talk_VTN = L9_1
L9_1 = "她是个坚强的孩子，一定会好起来的。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Sie ist ein starkes Mädchen. Ich bin sicher, sie erholt sich."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Elle est forte. Je sais qu'elle s'en sortira."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "COUNTERCASE_GAEUN_NORMAL_3@209#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 209
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 31353
L9_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "OFFICER_ADMIN_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "하지만 임시 의료 지원은 기간이 짧아요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "ですが、臨時の医療支援は期間が長くありません。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "But this temporary medical care won't last long."
L9_1.m_Talk_ENG = L10_1
L10_1 = "不過臨時醫療支援的時間很短。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "แต่การดูแลชั่วคราวจะอยู่ได้ไม่นาน"
L9_1.m_Talk_THA = L10_1
L10_1 = "Nhưng quá trình chăm sóc y tế tạm thời này sẽ không kéo dài được đâu."
L9_1.m_Talk_VTN = L10_1
L10_1 = "不过临时医疗支援时间很短。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Aber wir können sie nicht dauerhaft medizinisch versorgen."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Mais ces soins temporaires ne vont pas durer longtemps."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "COUNTERCASE_GAEUN_NORMAL_3@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 31353
L10_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "OFFICER_ADMIN_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "정식으로 장기적인 치료를 받으려면 관리국의 망명 허가가 필요합니다."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "正式に長期的な治療を受けるためには、管理局の亡命許可が必要です。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "In order to receive regular treatment, she'll need authorization from the Administration to be granted asylum."
L10_1.m_Talk_ENG = L11_1
L11_1 = "想要得到長期治療，必須要有管理局的難民許可。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เธอต้องได้รับอนุญาตจากองค์การบริหารโลกให้เป็นผู้ลี้ภัย เพื่อที่เธอจะได้รับการรักษาอย่างต่อเนื่อง"
L10_1.m_Talk_THA = L11_1
L11_1 = "Để nhận được liệu trình điều trị thường xuyên, cô ấy cần được Cục Quản Lý cho phép tị nạn."
L10_1.m_Talk_VTN = L11_1
L11_1 = "想要得到长期治疗，必须要有管理局的难民许可。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Um eine richtige Behandlung zu erhalten, muss die Administration ihr Asyl gewähren."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Pour recevoir un vrai traitement, elle aura besoin d'une autorisation de l'Administration pour qu'on lui accorde le droit d'asile."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "COUNTERCASE_GAEUN_NORMAL_3@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 31353
L11_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "OFFICER_ADMIN_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "아시겠지만 샤레이드가 관리국 직할 도시로 선포된 지 얼마 안 되서...... 허가 나기가 쉽지 않아요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ご存じだと思いますが、シャレードは管理局直轄都市になったばかりで……許可を取るのは難しいんです。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "As you know, Charade was just recently declared to be under the Administration's direct control... So the approval might not come so easily."
L11_1.m_Talk_ENG = L12_1
L12_1 = "如你所知，查雷德才剛宣布成為管理局的直轄城市……要獲得許可非常不容易。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "อย่างที่คุณรู้นะ องค์การบริหารโลกเพิ่งประกาศว่าชาเรดอยู่ภายใต้การควบคุมโดยตรงแล้ว... ดังนั้นการขออนุมัติอาจไม่ง่ายนัก"
L11_1.m_Talk_THA = L12_1
L12_1 = "Như anh biết đấy, gần đây Charade đã nằm dưới sự kiểm soát trực tiếp của Cục Quản Lý... Cho nên việc phê duyệt có thể không dễ dàng đâu."
L11_1.m_Talk_VTN = L12_1
L12_1 = "如你所知，距查雷德成为管理局直辖城市还没过多久……获得许可非常不容易。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Wie Sie wissen, befindet sich Charade noch nicht lange unter Kontrolle der Administration … Es könnte sich also als schwierig erweisen, die Zustimmung der Behörden zu erhalten."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Comme vous le savez, Charade est sous le contrôle direct de l'Administration depuis peu... Elle aura sans doute du mal à obtenir son approbation."
L11_1.m_Talk_FRA = L12_1
