L13_1.m_Talk_TWN = L14_1
L14_1 = "ไม่ต้องห่วงหรอก ยังไงก็ได้แน่"
L13_1.m_Talk_THA = L14_1
L14_1 = "Đừng lo lắng về chuyện đó. Sẽ được phê duyệt thôi."
L13_1.m_Talk_VTN = L14_1
L14_1 = "不用担心许可的事。我会拿到的。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Machen Sie sich darüber keine Sorgen. Wir werden die Zustimmung bekommen."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Ne vous inquiétez pas. Son traitement sera approuvé."
