L28_1 = "선생님, 어디 있어? 거기 있는 거 맞지? 나 보고 있지?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "先生、どこにいるの？　そこにいるんでしょ？　私を見てるよね？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Where are you, Teacher? You're there, right? You're watching me, aren't you?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "老師，您在哪？您在那邊吧？您在看我吧？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "คุณครูอยู่ไหนคะ? อยู่ตรงนั้นใช่มั้ย? ดูหนูอยู่ใช่มั้ย?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Anh đang ở đâu? Anh đang ở đó, phải không? Anh đang nhìn tôi, phải không?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "老师，你在哪？是不是在那边？您正在看着对吧？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Wo bist du, Lehrer? Du bist da, oder? Du schaust mir zu, oder?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Où êtes-vous, Professeur ? Vous êtes là, pas vrai ? Vous veillez sur moi, hein ?"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "COUNTERCASE_GAEUN_NORMAL_3@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 31353
L28_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L28_1.m_bWaitClick = true
