L28_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L28_1.m_Pos = "C"
L28_1.m_Crash = 30
L29_1 = "나, 앞으로 많이 웃을게. 그러니까 가지 마."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "私、これからたくさん笑う。だから行かないで。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I'm going to keep smiling from now on. So please don't leave me."
L28_1.m_Talk_ENG = L29_1
L29_1 = "我以後會常常笑的，所以不要走。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "จากนี้ไปหนูจะยิ้มค่ะ อย่าทิ้งหนูนะคะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Tôi sẽ tiếp tục mỉm cười từ bây giờ. Vây nên xin đừng rời xa tôi."
L28_1.m_Talk_VTN = L29_1
L29_1 = "我，以后会经常笑的，所以不要走好不好。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ab jetzt werde ich nur noch lächeln, versprochen. Bitte bleib bei mir."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Je vais sourire à partir de maintenant. Alors ne me laissez pas, s'il vous plaît."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
