L30_1 = "나...... 나 앞으로도 선생님이랑 같이 있을래......"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "私……これからも先生と一緒にいたい……"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I... I want to stay by your side..."
L29_1.m_Talk_ENG = L30_1
L30_1 = "我……我以後也想和老師在一起……"
L29_1.m_Talk_TWN = L30_1
L30_1 = "หนู... หนูอยากอยู่ข้างๆ คุณ..."
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi... tôi muốn ở bên cạnh bạn..."
L29_1.m_Talk_VTN = L30_1
L30_1 = "我……我以后也想和老师在一起……"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ich … ich will an deiner Seite bleiben …"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Je... Je veux rester avec vous..."
L29_1.m_Talk_FRA = L30_1
