L33_1 = "NURSE_NPC_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "후우, 같이 오신 분이라면 벌써 떠나셨단다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ふう、一緒に来た方ならもうここを去ったわよ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Phew... The person who brought you here already left."
L32_1.m_Talk_ENG = L33_1
L33_1 = "唉，如果妳在找和妳一起來的人，他已經走掉了。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เฮ้อ... คนที่พาเธอมาส่งที่นี่เขาไปแล้วนะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Phù... Người đưa nhóc đến đây đã rời đi rồi."
L32_1.m_Talk_VTN = L33_1
L33_1 = "呼，如果你在找一起来的人，他已经走掉了。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Du meine Güte … Der Mensch, der dich hierher gebracht hat, ist schon wieder verschwunden."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Ouf... La personne qui t'a emmenée ici est déjà partie."
L32_1.m_Talk_FRA = L33_1
