L36_1 = "NURSE_NPC_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "거짓말이 아니야. 자, 너한테 읽어 주라고 하셨던 쪽지란다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "嘘じゃないわ。ほら、あなたに読ませてほしいと渡された手紙なの。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I'm not lying. Here. This Teacher of yours asked me to read you this note."
L35_1.m_Talk_ENG = L36_1
L36_1 = "我沒有騙人。來，這是他留給妳的訊息。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ฉันไม่ได้โกหก นี่ คุณครูของเธอฝากฉันอ่านจดหมายนี้ให้เธอฟัง"
L35_1.m_Talk_THA = L36_1
L36_1 = "Chị không nói dối. Đây. Giáo Viên của em đã nhờ chị đọc cho em lá thư này."
L35_1.m_Talk_VTN = L36_1
L36_1 = "不是骗人。来，这是他留给你的纸条。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Nein, ich lüge nicht. Hier. Dieser Lehrer von dir hat mich gebeten, dir etwas vorzulesen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Je ne mens pas. Tiens. Ton Professeur m'a demandé de te lire ce message."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
