L42_1 = "COUNTERCASE_GAEUN_NORMAL_3@241#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 241
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 31353
L41_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
