L41_1.m_fWaitTime = 0
L42_1 = "ADMIN_COFFIN_NULL_QM"
L41_1.m_CharStrID = L42_1
L42_1 = "말도 없이 떠나서 미안하구나."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "何も言わずに立ち去ってすまないね。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I'm sorry I left without saying anything."
L41_1.m_Talk_ENG = L42_1
L42_1 = "對不起，我一句話也沒說就離開了。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ขอโทษที่จากไปโดยไม่พูดอะไรนะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Xin lỗi vì đã bỏ đi mà không nói gì."
L41_1.m_Talk_VTN = L42_1
L42_1 = "对不起，我一句话也没说就离开了。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Verzeih, dass ich, ohne etwas zu sagen, gehen musste."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Je suis désolé d'être parti sans te prévenir."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "COUNTERCASE_GAEUN_NORMAL_3@242#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 242
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 31353
L42_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "ADMIN_COFFIN_NULL_QM"
L42_1.m_CharStrID = L43_1
L43_1 = "하지만 내가 하는 일은 아주 위험한 것들이고, 또 무서운 적들도 많이 있단다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "でも私の仕事はとても危険なことばかりで、恐ろしい敵もたくさんいる。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "But I'm involved in a very dangerous line of work. I also have many formidable foes."
L42_1.m_Talk_ENG = L43_1
L43_1 = "但我的工作非常危險，還有很多很可怕的敵人。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "แต่ฉันเกี่ยวข้องกับงานที่อันตรายมาก แถมยังมีศัตรูที่น่ากลัวมากมาย"
L42_1.m_Talk_THA = L43_1
L43_1 = "Nhưng tôi đang tham gia vào một công việc rất nguy hiểm. Tôi cũng có rất nhiều kẻ thù đáng sợ."
L42_1.m_Talk_VTN = L43_1
L43_1 = "但是我的工作非常危险，常常要面对许多可怕的敌人。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Aber ich arbeite auf einem sehr gefährlichen Gebiet und habe einige sehr mächtige Feinde."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Mais mon travail est très dangereux et je suis entouré d'ennemis redoutables."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
