L43_1.m_fWaitTime = 0
L44_1 = "ADMIN_COFFIN_NULL_QM"
L43_1.m_CharStrID = L44_1
L44_1 = "나와 관계되어서 널 위험에 처하게 하고 싶지는 않아."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "私と関わらせて、君を危険な目に遭わせたくはないんだ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I wouldn't want to put you in harm's way because of me."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我不想因為我的關係，害妳身陷在危險之中。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันไม่อยากให้เธอต้องเป็นอันตรายเพราะฉัน"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi sẽ không muốn bạn bị thương vì tôi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "我不想你因为与我有关联，而处于危险之中。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich könnte mir nie verzeihen, dich in Gefahr zu bringen."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je ne veux pas que tu sois en danger à cause de moi."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "COUNTERCASE_GAEUN_NORMAL_3@244#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 244
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 31353
L44_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L44_1.m_bWaitClick = true
