L45_1 = "UNIT_DESPAIR"
L44_1.m_Face = L45_1
L44_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L44_1.m_Pos = "C"
L44_1.m_Crash = 20
L45_1 = "위, 위험 같은 거 상관없단 말이야......!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "き、危険なんてどうだっていいのに……！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I-I don't care how dangerous it is!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "我、我才不在乎什麼危險……！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "นะ-หนูไม่แคร์ว่ามันจะอันตรายแค่ไหน!"
L44_1.m_Talk_THA = L45_1
L45_1 = "T-tôi không quan tâm đến nguy hiểm!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "我，我不在乎什么危险……！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "M-mir ist egal, wie gefährlich das ist!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Je... Je m'en fiche, que ça soit dangereux !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "COUNTERCASE_GAEUN_NORMAL_3@245#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 245
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 31353
L45_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "GAEUN_CHILD_NULL_NULL"
L45_1.m_Pos = "C"
L45_1.m_Crash = 20
L46_1 = "싫어...... 나, 나 방해 안 할 건데...... 나도 도와 줄 수 있는데......"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "嫌よ……わ、私邪魔しないから……私も手伝えるのに……"
L45_1.m_Talk_JPN = L46_1
L46_1 = "No... I-I can stay out of your way... I can help you too..."
L45_1.m_Talk_ENG = L46_1
L46_1 = "不要……我、我不會妨礙您的……我能幫上您的忙……"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ไม่... หนูจะไม่เกะกะคุณ... หนูช่วยคุณได้ด้วยนะ..."
L45_1.m_Talk_THA = L46_1
L46_1 = "Không... Tôi-tôi có thể dọn đường cho anh... tôi cũng có thể giúp anh mà..."
L45_1.m_Talk_VTN = L46_1
L46_1 = "不要……我，我不会妨碍您的……明明我能帮得上忙……"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Nein, nein, nein … Ich werde dir nicht im Weg stehen … Ich kann dir helfen …"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Non... Je ne serai pas un fardeau... Je peux vous aider..."
L45_1.m_Talk_FRA = L46_1
