L48_1 = "COUNTERCASE_GAEUN_NORMAL_3@247#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 247
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 31353
L47_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "ADMIN_COFFIN_NULL_QM"
L47_1.m_CharStrID = L48_1
L48_1 = "말했듯이 나는 아주 많은 실패를 겪었단다. 그리고 그만큼 구하지 못한 사람들도 많아."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "前にも言ったが、私はたくさんの失敗を経験してきた。その数だけ救えなかった人も多い。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Like I said, I've been through lots of failure. I also failed to save many lives in the process."
L47_1.m_Talk_ENG = L48_1
L48_1 = "就像我說過的，我經歷了很多次的失敗，還有很多沒能拯救的人們。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "อย่างที่ฉันบอก ฉันผ่านความล้มเหลวมามาก แถมยังล้มเหลวในการช่วยชีวิตคนมากมาย"
L47_1.m_Talk_THA = L48_1
L48_1 = "Như tôi đã kể, tôi đã trải qua rất nhiều thất bại. Tôi cũng đã thất bại trong việc cứu sống nhiều người trong quá trình này."
L47_1.m_Talk_VTN = L48_1
L48_1 = "如我所说，我有很多次失败。还有很多没能拯救的人们。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Wie ich schon gesagt habe, habe ich oft versagt. Ich habe auch dabei versagt, viele Leben zu retten."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Comme je te l'ai dit, j'ai connu mon lot d'échecs. J'ai également échoué à sauver de nombreuses vies."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "COUNTERCASE_GAEUN_NORMAL_3@248#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 248
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 31353
L48_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "ADMIN_COFFIN_NULL_QM"
L48_1.m_CharStrID = L49_1
L49_1 = "하지만 이번에는 너를 구하는 데 성공했어."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "でも今回は君を救うことができた。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "But this time, I managed to save you."
L48_1.m_Talk_ENG = L49_1
L49_1 = "不過這次我成功救了妳。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "แต่คราวนี้ฉันช่วยเธอได้"
L48_1.m_Talk_THA = L49_1
L49_1 = "Nhưng lần này, tôi đã cứu được bạn."
L48_1.m_Talk_VTN = L49_1
L49_1 = "不过这次我成功救了你。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Aber bei dir ist es mir gelungen."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Mais cette fois, j'ai pu te sauver."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "COUNTERCASE_GAEUN_NORMAL_3@249#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 249
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 31353
L49_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "ADMIN_COFFIN_NULL_QM"
L49_1.m_CharStrID = L50_1
L50_1 = "그러니까 내가 그 사실을 자랑스럽게 여길 수 있게......"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "だから、私がその事実を誇らしく思えるように……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "So let me take some pride in this one victory..."
L49_1.m_Talk_ENG = L50_1
L50_1 = "所以，為了能讓我對這件事感到驕傲……"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฉันขอบภาคภูมิใจในชัยชนะหนึ่งเดียวครั้งนี้หน่อยแล้วกัน..."
L49_1.m_Talk_THA = L50_1
L50_1 = "Nên hãy để tôi tự hào về chiến thắng này nhé..."
L49_1.m_Talk_VTN = L50_1
L50_1 = "所以为了能让我对此感到自豪……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Also lass mich stolz sein auf diesen einen Sieg …"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Alors laisse-moi savourer cette victoire..."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "COUNTERCASE_GAEUN_NORMAL_3@250#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 250
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 31353
L50_1.m_CutScenStrID = "COUNTERCASE_GAEUN_NORMAL_3"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "ADMIN_COFFIN_NULL_QM"
L50_1.m_CharStrID = L51_1
L51_1 = "앞으로도, 웃으면서 지내 주렴."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "これからも、笑顔で過ごしてほしい。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Always stay smiling."
L50_1.m_Talk_ENG = L51_1
L51_1 = "之後也，笑著活下去吧。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ยิ้มเข้าไว้นะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Hãy luôn mỉm cười."
L50_1.m_Talk_VTN = L51_1
L51_1 = "未来也，笑着活下去吧。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Geh lächelnd durchs Leben."
L50_1.m_Talk_DEU = L51_1
L51_1 = "N'arrête jamais de sourire."
L50_1.m_Talk_FRA = L51_1
